// =============================================================================
// Contract Boundary Guard
// =============================================================================
// Tracks contract violations and provides mismatch statistics.
// Single source of truth for contract health monitoring.
// =============================================================================

export interface ContractViolationRecord {
  code: 'SCHEMA_MISMATCH' | 'NETWORK_ERROR' | 'UNKNOWN'
  message: string
  context: string
  timestamp: number
  details?: unknown
}

export interface ContractStats {
  totalCalls: number
  successCount: number
  violationCount: number
  violationsByContext: Record<string, number>
  recentViolations: ContractViolationRecord[]
  healthScore: number
}

const MAX_RECENT_VIOLATIONS = 50

class ContractGuard {
  private totalCalls = 0
  private successCount = 0
  private violations: ContractViolationRecord[] = []
  private violationsByContext: Record<string, number> = {}

  recordSuccess(context: string): void {
    this.totalCalls++
    this.successCount++
  }

  recordViolation(violation: ContractViolationRecord): void {
    this.totalCalls++
    this.violations.push(violation)

    if (this.violations.length > MAX_RECENT_VIOLATIONS) {
      this.violations = this.violations.slice(-MAX_RECENT_VIOLATIONS)
    }

    this.violationsByContext[violation.context] =
      (this.violationsByContext[violation.context] || 0) + 1
  }

  getStats(): ContractStats {
    return {
      totalCalls: this.totalCalls,
      successCount: this.successCount,
      violationCount: this.violations.length,
      violationsByContext: { ...this.violationsByContext },
      recentViolations: [...this.violations],
      healthScore: this.totalCalls > 0
        ? Math.round((this.successCount / this.totalCalls) * 100)
        : 100,
    }
  }

  hasViolations(): boolean {
    return this.violations.length > 0
  }

  getViolationsForContext(context: string): ContractViolationRecord[] {
    return this.violations.filter(v => v.context === context)
  }

  reset(): void {
    this.totalCalls = 0
    this.successCount = 0
    this.violations = []
    this.violationsByContext = {}
  }
}

export const contractGuard = new ContractGuard()

import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Link } from '@tanstack/react-router'
import api from '../api/index'

const TENANT_ID = 'ten_307b8956545642a9a45097f2f480a7b4'
const PROJECT_ID = 'prj_6802ca7a12c24aafa31cf77fa63890be'

interface MetricsData {
  projectId: string
  lookback: string
  generatedAt: string
  stateCounts: Record<string, number>
  health: Record<string, number>
  warnings: string[]
}

function useMetrics() {
  return useQuery({
    queryKey: ['admin-metrics', PROJECT_ID],
    queryFn: () => api.get(`/render/projects/${PROJECT_ID}/jobs/metrics?lookback=PT24H`).then(r => r.data as MetricsData),
  })
}

function MetricCard({ label, value, color = 'text-white' }: { label: string; value: number; color?: string }) {
  return (
    <div className="rounded-lg border border-gray-800 bg-gray-900 p-4">
      <div className="text-sm text-gray-400">{label}</div>
      <div className={`text-2xl font-bold ${color}`}>{value}</div>
    </div>
  )
}

function WarningBadge({ warning }: { warning: string }) {
  const colors: Record<string, string> = {
    'STALE_EXECUTING_JOBS_PRESENT': 'bg-red-900 text-red-200',
    'RETRY_ELIGIBLE_FAILED_JOBS_PRESENT': 'bg-yellow-900 text-yellow-200',
    'RETRY_EXHAUSTED_JOBS_PRESENT': 'bg-orange-900 text-orange-200',
    'OLD_QUEUED_JOB': 'bg-purple-900 text-purple-200',
  }
  return (
    <span className={`inline-block rounded px-2 py-1 text-xs ${colors[warning] || 'bg-gray-800 text-gray-300'}`}>
      {warning.replace(/_/g, ' ')}
    </span>
  )
}

export default function AdminRenderJobsPage() {
  const { data: metrics, isLoading, error } = useMetrics()
  const [selectedStatus, setSelectedStatus] = useState<string>('ALL')

  const stateCounts = metrics?.stateCounts || {}
  const health = metrics?.health || {}
  const warnings = metrics?.warnings || []

  const statusFilters = ['ALL', 'QUEUED', 'EXECUTING', 'COMPLETED', 'FAILED']

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100">
      {/* Header */}
      <div className="border-b border-gray-800 px-6 py-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold">Render Jobs</h1>
            <p className="text-sm text-gray-400">Manage and inspect render job execution state</p>
          </div>
          <span className="rounded bg-blue-900 px-2 py-1 text-xs text-blue-200">Admin Console</span>
        </div>
      </div>

      <div className="p-6">
        {/* Warnings */}
        {warnings.length > 0 && (
          <div className="mb-6 flex flex-wrap gap-2">
            {warnings.map((w, i) => <WarningBadge key={i} warning={w} />)}
          </div>
        )}

        {/* Metrics Cards */}
        <div className="mb-6 grid grid-cols-2 gap-4 md:grid-cols-4">
          {isLoading ? (
            <div className="col-span-4 text-center text-gray-400">Loading metrics...</div>
          ) : error ? (
            <div className="col-span-4 text-center text-red-400">Failed to load metrics</div>
          ) : (
            <>
              <MetricCard label="Queued" value={stateCounts.queued || 0} />
              <MetricCard label="Executing" value={stateCounts.executing || 0} />
              <MetricCard label="Completed" value={stateCounts.completed || 0} color="text-green-400" />
              <MetricCard label="Failed" value={stateCounts.failed || 0} color="text-red-400" />
              <MetricCard label="Stale Executing" value={health.staleExecuting || 0} color="text-red-400" />
              <MetricCard label="Retry Eligible" value={health.retryEligibleFailed || 0} color="text-yellow-400" />
              <MetricCard label="Retry Exhausted" value={health.retryExhausted || 0} color="text-orange-400" />
              <MetricCard label="Total" value={Object.values(stateCounts).reduce((a, b) => a + b, 0)} />
            </>
          )}
        </div>

        {/* Status Filters */}
        <div className="mb-4 flex gap-2">
          {statusFilters.map(status => (
            <button
              key={status}
              onClick={() => setSelectedStatus(status)}
              className={`rounded px-3 py-1 text-sm ${
                selectedStatus === status
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
              }`}
            >
              {status}
            </button>
          ))}
        </div>

        {/* Info */}
        <div className="rounded-lg border border-gray-800 bg-gray-900 p-4">
          <h2 className="mb-2 font-semibold">RenderJob List</h2>
          <p className="text-sm text-gray-400">
            RenderJob list API is not yet available. This view shows metrics summary only.
          </p>
          <p className="mt-2 text-sm text-gray-400">
            For detailed per-job lifecycle events, visit{' '}
            <Link to="/dev/timeline-git" className="text-blue-400 hover:underline">
              /dev/timeline-git
            </Link>
          </p>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useQuery, useMutation } from '@tanstack/react-query'
import api from '../api/index'
import type { ArtifactListResponse, ArtifactSummary } from '../contracts/app/artifact'

const DEV_TENANT_ID = 'ten_307b8956545642a9a45097f2f480a7b4'
const DEV_PROJECT_ID = 'prj_6802ca7a12c24aafa31cf77fa63890be'

// Health check
function useHealth() {
  return useQuery({
    queryKey: ['health'],
    queryFn: () => api.get('/actuator/health').then(r => r.data),
    refetchInterval: 30000,
  })
}

// Dev token
function useDevToken() {
  return useQuery({
    queryKey: ['devToken'],
    queryFn: () => api.post('/dev/auth/token', { tenantId: 'smoke-tenant', userId: 'dev-console' })
      .then(r => r.data.accessToken),
    staleTime: 300000,
  })
}

// Submit synthetic render
function useSubmitRender(token: string | undefined) {
  return useMutation({
    mutationFn: () => {
      if (!token) throw new Error('No token')
      return api.post(`/tenants/${DEV_TENANT_ID}/projects/${DEV_PROJECT_ID}/render-jobs/incremental/submit`, {
        tenantId: DEV_TENANT_ID,
        projectId: DEV_PROJECT_ID,
        prompt: JSON.stringify({
          version: '1.0',
          tracks: [{ id: 'v1', type: 'video', clips: [{ id: 'c1', source: 'testsrc', duration: 2 }] }]
        }),
        profile: 'synthetic_testsrc',
      }, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.data)
    },
  })
}

// Poll job status
function useJobStatus(token: string | undefined, jobId: string | null) {
  return useQuery({
    queryKey: ['jobStatus', jobId],
    queryFn: () => {
      if (!token || !jobId) throw new Error('Missing')
      return api.get(`/render/jobs/${jobId}`, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.data)
    },
    enabled: !!token && !!jobId,
    refetchInterval: (query: any) => {
      const status = query.state.data?.status
      return ['COMPLETED', 'FAILED', 'CANCELLED', 'REJECTED'].includes(status) ? false : 1500
    },
  })
}

// Get artifacts
function useArtifacts(token: string | undefined, jobId: string | null, jobStatus: string | undefined) {
  return useQuery({
    queryKey: ['artifacts', jobId],
    queryFn: () => {
      if (!token || !jobId) throw new Error('Missing')
      return api.get<ArtifactListResponse>(
        `/tenants/${DEV_TENANT_ID}/projects/${DEV_PROJECT_ID}/render-jobs/${jobId}/artifacts`,
        { headers: { Authorization: `Bearer ${token}` } }
      ).then(r => r.data)
    },
    enabled: !!token && !!jobId && jobStatus === 'COMPLETED',
  })
}

const TERMINAL_STATES = ['COMPLETED', 'FAILED', 'CANCELLED', 'REJECTED']
const STATUS_ORDER = ['QUEUED', 'SELECTING_PROVIDER', 'PROVIDER_SELECTED', 'EXECUTING', 'COMPLETING', 'COMPLETED']

export function DevConsolePage() {
  const health = useHealth()
  const token = useDevToken().data
  const submitMutation = useSubmitRender(token)
  const [jobId, setJobId] = useState<string | null>(null)
  const jobStatus = useJobStatus(token, jobId)
  const artifacts = useArtifacts(token, jobId, jobStatus.data?.status)

  const handleSubmit = () => {
    submitMutation.mutate(undefined, {
      onSuccess: (data) => setJobId(data.jobId),
    })
  }

  const isRunning = jobId && !TERMINAL_STATES.includes(jobStatus.data?.status)
  const isCompleted = jobStatus.data?.status === 'COMPLETED'
  const isFailed = TERMINAL_STATES.includes(jobStatus.data?.status) && !isCompleted

  return (
    <div style={{ padding: '24px', fontFamily: 'monospace', maxWidth: '1200px', color: '#e0e0e0' }}>
      <h1>🔧 Developer Preview Console</h1>
      <p style={{ color: '#888' }}>Diagnostic view for API workflows. Not a product UI.</p>

      {/* API Health */}
      <section style={{ marginBottom: '24px', padding: '16px', background: '#1a1a1a', borderRadius: '8px' }}>
        <h2>📡 API Health</h2>
        <div>Base URL: <code>{import.meta.env.VITE_API_BASE_URL || 'https://api.render.cc.cd'}</code></div>
        <div>Status: {health.isLoading ? 'Loading...' : health.data?.status === 'UP' ? '✅ UP' : '❌ DOWN'}</div>
        <button onClick={() => health.refetch()} style={{ marginTop: '8px' }}>Refresh</button>
      </section>

      {/* Synthetic Render Test */}
      <section style={{ marginBottom: '24px', padding: '16px', background: '#1a1a1a', borderRadius: '8px' }}>
        <h2>🎬 Synthetic Render Test</h2>
        <p style={{ color: '#888', fontSize: '14px', marginBottom: '12px' }}>
          Runs a preview-only synthetic FFmpeg test render (testsrc, 2s, 320x180).<br />
          This validates the preview FFmpeg bootstrap path. It does not use OpenCue and is not the final production execution architecture.
        </p>
        <div style={{ marginBottom: '8px', fontSize: '12px', color: '#666' }}>
          Execution Plane: READY for preview FFmpeg bootstrap | OpenCue: NOT STARTED
        </div>

        <button
          onClick={handleSubmit}
          disabled={submitMutation.isPending || !!isRunning}
          style={{
            padding: '10px 20px',
            background: submitMutation.isPending || isRunning ? '#333' : '#2563eb',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: submitMutation.isPending || isRunning ? 'not-allowed' : 'pointer',
            fontSize: '14px',
          }}
        >
          {submitMutation.isPending ? 'Submitting...' : isRunning ? 'Running...' : 'Create Synthetic Render'}
        </button>

        {submitMutation.isError && (
          <div style={{ marginTop: '8px', color: '#ef4444' }}>❌ Submit failed: {(submitMutation.error as any)?.message || 'Unknown error'}</div>
        )}

        {/* Job Status */}
        {jobId && (
          <div style={{ marginTop: '16px' }}>
            <div>Job: <code>{jobId}</code></div>

            {/* Status Timeline */}
            <div style={{ marginTop: '12px', display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
              {STATUS_ORDER.map((s) => {
                const current = jobStatus.data?.status
                const idx = STATUS_ORDER.indexOf(current)
                const stepIdx = STATUS_ORDER.indexOf(s)
                const isActive = s === current
                const isPast = stepIdx < idx
                const isTerminal = s === 'COMPLETED' && current === 'COMPLETED'
                return (
                  <div key={s} style={{
                    padding: '4px 10px',
                    borderRadius: '4px',
                    fontSize: '12px',
                    background: isActive ? '#2563eb' : isPast || isTerminal ? '#166534' : '#333',
                    color: isActive || isPast || isTerminal ? 'white' : '#666',
                    border: isActive ? '1px solid #60a5fa' : '1px solid transparent',
                  }}>
                    {s}
                  </div>
                )
              })}
            </div>

            {jobStatus.isLoading && <div style={{ marginTop: '8px', color: '#888' }}>Polling...</div>}

            {/* Failure */}
            {isFailed && (
              <div style={{ marginTop: '12px', padding: '12px', background: '#7f1d1d', borderRadius: '6px' }}>
                ❌ Job failed with status: <strong>{jobStatus.data?.status}</strong>
              </div>
            )}

            {/* Artifacts */}
            {isCompleted && artifacts.data && (
              <div style={{ marginTop: '16px' }}>
                <h3>📦 Artifacts ({artifacts.data.total})</h3>
                {artifacts.data.items.length === 0 && (
                  <div style={{ color: '#eab308' }}>⚠️ No artifacts found</div>
                )}
                {artifacts.data.items.map((artifact) => (
                  <ArtifactCard key={artifact.id} artifact={artifact} jobId={jobId} token={token} />
                ))}
              </div>
            )}
          </div>
        )}
      </section>
    </div>
  )
}

function ArtifactCard({ artifact, jobId, token }: { artifact: ArtifactSummary; jobId: string; token: string }) {
  const requestAccess = async () => {
    const response = await api.get(
      `/tenants/${DEV_TENANT_ID}/projects/${DEV_PROJECT_ID}/render-jobs/${jobId}/artifacts/${artifact.id}/access`,
      { headers: { Authorization: `Bearer ${token}` } }
    )
    window.open(response.data.access.accessUrl, '_blank', 'noopener,noreferrer')
  }

  return (
    <div style={{ marginTop: '12px', padding: '12px', background: '#111', borderRadius: '6px', border: '1px solid #333' }}>
      <div style={{ fontSize: '12px', color: '#888' }}>
        <div>ID: <code>{artifact.id}</code></div>
        <div>Type: {artifact.type} | Kind: {artifact.kind} | State: {artifact.state}</div>
        <div>Integrity: {artifact.integrityState} | Bytes: {artifact.byteLength}</div>
        <div>Created: {artifact.createdAt}</div>
      </div>
      <div style={{ marginTop: '12px' }}>
        <button onClick={requestAccess} style={{ color: '#60a5fa', fontSize: '12px' }}>
          Request ephemeral access
        </button>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import api from '../api/index'

const TENANT_ID = 'ten_307b8956545642a9a45097f2f480a7b4'
const PROJECT_ID = 'prj_6802ca7a12c24aafa31cf77fa63890be'

// Types
interface TimelineRevision {
  id: string
  revisionNumber: number
  parentRevisionId: string | null
  snapshotId: string
  internalRevision: number
  source: string
  message: string | null
  labels: string[]
  authorUserId: string | null
  editSessionId: string | null
  patchOpCount: number
  createdAt: string
  changeSummary: {
    supported: boolean
    tracksAdded: number
    tracksRemoved: number
    tracksModified: number
    clipsAdded: number
    clipsRemoved: number
    clipsModified: number
    assetsAdded: number
    assetsRemoved: number
  }
  isMerge: boolean
}

interface SemanticChange {
  changeType: string
  entityKind: string
  entityId: string
  description: string
  renderAffecting: boolean
}

interface CompareResponse {
  fromRevision: TimelineRevision
  toRevision: TimelineRevision
  summary: {
    supported: boolean
    tracksAdded: number
    clipsAdded: number
    assetsAdded: number
  }
  entityChanges: Array<{ kind: string; entityId: string; action: string }>
  semanticDiff: {
    supported: boolean
    structurallyEqual: boolean
    changeCount: number
    changes: SemanticChange[]
  }
  patchPaths: Array<{ op: string; path: string }>
  patchOpCount: number
}

interface RenderResponse {
  renderJobId: string | null
  timelineRevisionId: string
  snapshotId: string | null
  outputProductId: string | null
  productStatus: string
  storageReferenceId: string | null
  mimeType: string | null
  outputFormat: string | null
  width: number
  height: number
  fps: number
  durationSeconds: number
  hasSubtitles: boolean
  baselineRenderer: string | null
  renderMode: string | null
  inputProductIds: string[]
  inputDependencyCount: number
  message: string
}

// Hooks
function useRevisions() {
  return useQuery({
    queryKey: ['timeline-revisions', PROJECT_ID],
    queryFn: () => api.get(`/render/projects/${PROJECT_ID}/timeline/revisions`).then(r => r.data as TimelineRevision[]),
  })
}

function useRevision(revisionId: string | null) {
  return useQuery({
    queryKey: ['timeline-revision', PROJECT_ID, revisionId],
    queryFn: () => api.get(`/render/projects/${PROJECT_ID}/timeline/revisions/${revisionId}`).then(r => r.data),
    enabled: !!revisionId,
  })
}

function useSnapshot(revisionId: string | null) {
  return useQuery({
    queryKey: ['timeline-snapshot', PROJECT_ID, revisionId],
    queryFn: () => api.get(`/render/projects/${PROJECT_ID}/timeline/revisions/${revisionId}/snapshot`).then(r => r.data),
    enabled: !!revisionId,
  })
}

function useCompare(fromId: string | null, toId: string | null) {
  return useQuery({
    queryKey: ['timeline-compare', PROJECT_ID, fromId, toId],
    queryFn: () => api.get(`/render/projects/${PROJECT_ID}/timeline/revisions/compare?from=${fromId}&to=${toId}`).then(r => r.data as CompareResponse),
    enabled: !!fromId && !!toId,
  })
}

// RenderJob Status hooks
function useRenderJobEvents(renderJobId: string | null) {
  return useQuery({
    queryKey: ["render-job-events", PROJECT_ID, renderJobId],
    queryFn: () => api.get(`/render/projects/${PROJECT_ID}/jobs/${renderJobId}/events`).then(r => r.data),
    enabled: !!renderJobId,
  })
}

function useRenderWorkerMetrics() {
  return useQuery({
    queryKey: ["render-worker-metrics", PROJECT_ID],
    queryFn: () => api.get(`/render/projects/${PROJECT_ID}/jobs/metrics?lookback=PT1H`).then(r => r.data),
  })
}

function useRenderRevision() {
  return useMutation({
    mutationFn: (revisionId: string) =>
      api.post(`/render/projects/${PROJECT_ID}/timeline/revisions/${revisionId}/render`, { outputProfile: 'default_1080p' })
        .then(r => r.data as RenderResponse),
  })
}

function useRestoreRevision() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (revisionId: string) =>
      api.post(`/render/projects/${PROJECT_ID}/timeline/revisions/${revisionId}/restore`, { message: 'Restored from console' })
        .then(r => r.data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['timeline-revisions', PROJECT_ID] })
    },
  })
}

// Components
function RevisionList({ revisions, selectedId, onSelect }: { revisions: TimelineRevision[]; selectedId: string | null; onSelect: (id: string) => void }) {
  return (
    <div style={{ borderRight: '1px solid #333', padding: 8, overflowY: 'auto', height: '100%' }}>
      <h3 style={{ margin: '0 0 8px', fontSize: 14 }}>Revisions ({revisions.length})</h3>
      {revisions.map((rev, i) => (
        <div
          key={rev.id}
          onClick={() => onSelect(rev.id)}
          style={{
            padding: 6,
            marginBottom: 4,
            cursor: 'pointer',
            background: rev.id === selectedId ? '#1a3a5c' : i === 0 ? '#1a2a1a' : 'transparent',
            borderRadius: 4,
            borderLeft: i === 0 ? '3px solid #4ade80' : rev.id === selectedId ? '3px solid #60a5fa' : '3px solid transparent',
          }}
        >
          <div style={{ fontSize: 12, fontWeight: 600 }}>
            #{rev.revisionNumber}
            {i === 0 && <span style={{ color: '#4ade80', marginLeft: 4 }}>HEAD</span>}
            {rev.isMerge && <span style={{ color: '#f59e0b', marginLeft: 4 }}>MERGE</span>}
