// =============================================================================
// Timeline Command Engine
// =============================================================================
// Central engine for executing, undoing, and redoing timeline commands.
// All timeline mutations MUST go through this engine.
//
// Features:
// - Execute commands with validation
// - Undo/redo with history stack
// - Replay commands from history
// - Configurable max history size
// =============================================================================

import type {
  TimelineCommand,
  CommandResult,
  CommandType,
} from './types'
import type { TimelineCanvasState } from '../model/timeline'

// ---------------------------------------------------------------------------
// History Entry
// ---------------------------------------------------------------------------
export interface HistoryEntry {
  readonly command: TimelineCommand
  readonly result: CommandResult
  readonly executedAt: number
}

// ---------------------------------------------------------------------------
// Command Engine State
// ---------------------------------------------------------------------------
export interface CommandEngineState {
  readonly undoStack: readonly HistoryEntry[]
  readonly redoStack: readonly HistoryEntry[]
  readonly lastCommand: HistoryEntry | null
  readonly isReplaying: boolean
  readonly totalExecuted: number
}

// ---------------------------------------------------------------------------
// Command Engine Configuration
// ---------------------------------------------------------------------------
export interface CommandEngineConfig {
  readonly maxHistorySize: number
  readonly enableLogging: boolean
}

const DEFAULT_CONFIG: CommandEngineConfig = {
  maxHistorySize: 100,
  enableLogging: false,
}

// ---------------------------------------------------------------------------
// Command Engine
// ---------------------------------------------------------------------------
export class CommandEngine {
  private undoStack: HistoryEntry[] = []
  private redoStack: HistoryEntry[] = []
  private lastCommand: HistoryEntry | null = null
  private isReplaying = false
  private totalExecuted = 0
  private config: CommandEngineConfig

  constructor(config: Partial<CommandEngineConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  // -------------------------------------------------------------------------
  // Execute
  // -------------------------------------------------------------------------
  execute(
    command: TimelineCommand,
    currentTimeline: TimelineCanvasState
  ): CommandResult {
    if (this.isReplaying) {
      return { success: false, timeline: currentTimeline, errors: ['Cannot execute during replay'] }
    }

    const result = command.execute(currentTimeline)

    if (!result.success) {
      if (this.config.enableLogging) {
        console.warn(`[CommandEngine] Command ${command.type} failed:`, result.errors)
      }
      return result
    }

    // Record in history
    const entry: HistoryEntry = {
      command,
      result,
      executedAt: Date.now(),
    }

    this.undoStack.push(entry)

    // Trim history if needed
    if (this.undoStack.length > this.config.maxHistorySize) {
      this.undoStack = this.undoStack.slice(-this.config.maxHistorySize)
    }

    // Clear redo stack on new action
    this.redoStack = []
    this.lastCommand = entry
    this.totalExecuted++

    if (this.config.enableLogging) {
      console.log(`[CommandEngine] Executed ${command.type}: ${command.metadata.userAction}`)
    }

    return result
  }

  // -------------------------------------------------------------------------
  // Undo
  // -------------------------------------------------------------------------
  undo(currentTimeline: TimelineCanvasState): CommandResult {
    if (this.undoStack.length === 0) {
      return { success: false, timeline: currentTimeline, errors: ['Nothing to undo'] }
    }

    const entry = this.undoStack.pop()!
    const result = entry.command.undo(currentTimeline)

    if (!result.success) {
      // Restore entry if undo failed
      this.undoStack.push(entry)
      return result
    }

    this.redoStack.push(entry)
    this.lastCommand = this.undoStack.length > 0 ? this.undoStack[this.undoStack.length - 1] : null

    if (this.config.enableLogging) {
      console.log(`[CommandEngine] Undid ${entry.command.type}: ${entry.command.metadata.userAction}`)
    }

    return result
  }

  // -------------------------------------------------------------------------
  // Redo
  // -------------------------------------------------------------------------
  redo(currentTimeline: TimelineCanvasState): CommandResult {
    if (this.redoStack.length === 0) {
      return { success: false, timeline: currentTimeline, errors: ['Nothing to redo'] }
    }

    const entry = this.redoStack.pop()!
    const result = entry.command.execute(currentTimeline)

    if (!result.success) {
      // Restore entry if redo failed
      this.redoStack.push(entry)
      return result
    }

    this.undoStack.push(entry)
    this.lastCommand = entry

    if (this.config.enableLogging) {
      console.log(`[CommandEngine] Redid ${entry.command.type}: ${entry.command.metadata.userAction}`)
    }

    return result
  }

  // -------------------------------------------------------------------------
  // Replay
  // -------------------------------------------------------------------------
  replay(
    commands: readonly TimelineCommand[],
    initialTimeline: TimelineCanvasState
  ): { timeline: TimelineCanvasState; errors: string[] } {
    this.isReplaying = true
    let currentTimeline = initialTimeline
    const allErrors: string[] = []

    for (const command of commands) {
      const result = command.execute(currentTimeline)
      if (result.success) {
        currentTimeline = result.timeline
      } else {
        allErrors.push(...result.errors)
        if (this.config.enableLogging) {
          console.warn(`[CommandEngine] Replay failed at ${command.type}:`, result.errors)
        }
        break
      }
    }

    this.isReplaying = false
    return { timeline: currentTimeline, errors: allErrors }
  }

  // -------------------------------------------------------------------------
  // Getters
  // -------------------------------------------------------------------------
  getState(): CommandEngineState {
    return {
      undoStack: [...this.undoStack],
      redoStack: [...this.redoStack],
      lastCommand: this.lastCommand,
      isReplaying: this.isReplaying,
      totalExecuted: this.totalExecuted,
    }
  }

  canUndo(): boolean {
    return this.undoStack.length > 0
  }

  canRedo(): boolean {
    return this.redoStack.length > 0
  }

  getHistory(): readonly HistoryEntry[] {
    return [...this.undoStack]
  }

  getRedoStack(): readonly HistoryEntry[] {
    return [...this.redoStack]
  }

  // -------------------------------------------------------------------------
  // Clear
  // -------------------------------------------------------------------------
  clear(): void {
    this.undoStack = []
    this.redoStack = []
    this.lastCommand = null
    this.totalExecuted = 0
  }
}

// ---------------------------------------------------------------------------
// Singleton Instance
// ---------------------------------------------------------------------------
export const commandEngine = new CommandEngine({ enableLogging: true })

// =============================================================================
// AddClipCommand
// =============================================================================
// Adds a new clip to the timeline.
// =============================================================================

import type {
  TimelineCommand,
  CommandResult,
  CommandMetadata,
  AddClipPayload,
} from '../types'
import type { TimelineCanvasState } from '../../model/timeline'
import { generateCommandId } from '../types'

export class AddClipCommand implements TimelineCommand {
  readonly id: string
  readonly type = 'ADD_CLIP'
  readonly metadata: CommandMetadata
  readonly payload: AddClipPayload

  constructor(payload: AddClipPayload, metadata: CommandMetadata) {
    this.id = generateCommandId()
    this.payload = payload
    this.metadata = metadata
  }

  execute(timeline: TimelineCanvasState): CommandResult {
    const { clip } = this.payload
    const errors: string[] = []

    // Validate track exists
    const track = timeline.tracks[clip.trackId]
    if (!track) {
      return { success: false, timeline, errors: [`Track "${clip.trackId}" not found`] }
    }

    if (track.locked) {
      return { success: false, timeline, errors: [`Track "${track.name}" is locked`] }
    }

    // Add clip
    const clips = { ...timeline.clips, [clip.id]: clip }

    // Update track's clip list
    const tracks = {
      ...timeline.tracks,
      [clip.trackId]: {
        ...track,
        clipIds: [...track.clipIds, clip.id],
      },
    }

    // Recalculate duration
    const maxEnd = Object.values(clips).reduce(
      (max, c) => Math.max(max, c.timing.end),
      0
    )

    return {
      success: true,
      timeline: { ...timeline, tracks, clips, duration: maxEnd },
      errors,
    }
  }

  undo(timeline: TimelineCanvasState): CommandResult {
    const { clip } = this.payload
    const errors: string[] = []

    // Check clip exists
    if (!timeline.clips[clip.id]) {
      return { success: false, timeline, errors: [`Clip "${clip.id}" not found`] }
    }

    // Remove clip
    const { [clip.id]: _, ...remainingClips } = timeline.clips

    // Update track
    const track = timeline.tracks[clip.trackId]
    const tracks = track
      ? {
          ...timeline.tracks,
          [clip.trackId]: {
            ...track,
            clipIds: track.clipIds.filter((id) => id !== clip.id),
          },
        }
      : timeline.tracks

    // Recalculate duration
    const maxEnd = Object.values(remainingClips).reduce(
      (max, c) => Math.max(max, c.timing.end),
      0
    )

    return {
      success: true,
      timeline: { ...timeline, tracks, clips: remainingClips, duration: maxEnd },
      errors,
    }
  }
}

// =============================================================================
// DeleteClipCommand
// =============================================================================
// Deletes a clip from the timeline.
// =============================================================================

import type {
  TimelineCommand,
  CommandResult,
  CommandMetadata,
  DeleteClipPayload,
} from '../types'
import type { TimelineCanvasState } from '../../model/timeline'
import { generateCommandId } from '../types'

export class DeleteClipCommand implements TimelineCommand {
  readonly id: string
  readonly type = 'DELETE_CLIP'
  readonly metadata: CommandMetadata
  readonly payload: DeleteClipPayload

  constructor(payload: DeleteClipPayload, metadata: CommandMetadata) {
    this.id = generateCommandId()
    this.payload = payload
    this.metadata = metadata
  }

  execute(timeline: TimelineCanvasState): CommandResult {
    const { clip, trackId } = this.payload
    const errors: string[] = []

    // Check clip exists
    if (!timeline.clips[clip.id]) {
      return { success: false, timeline, errors: [`Clip "${clip.id}" not found`] }
    }

    // Check track not locked
    const track = timeline.tracks[trackId]
    if (track?.locked) {
      return { success: false, timeline, errors: [`Track "${track.name}" is locked`] }
    }

    // Remove clip
    const { [clip.id]: _, ...remainingClips } = timeline.clips

    // Update track
    const tracks = track
      ? {
          ...timeline.tracks,
          [trackId]: {
            ...track,
            clipIds: track.clipIds.filter((id) => id !== clip.id),
          },
        }
      : timeline.tracks

    // Recalculate duration
    const maxEnd = Object.values(remainingClips).reduce(
      (max, c) => Math.max(max, c.timing.end),
      0
    )

    return {
      success: true,
      timeline: { ...timeline, tracks, clips: remainingClips, duration: maxEnd },
      errors,
    }
  }

  undo(timeline: TimelineCanvasState): CommandResult {
    const { clip, trackId } = this.payload
    const errors: string[] = []

    // Validate track exists
    const track = timeline.tracks[trackId]
    if (!track) {
      return { success: false, timeline, errors: [`Track "${trackId}" not found`] }
    }

    // Restore clip
    const clips = { ...timeline.clips, [clip.id]: clip }

    // Update track
    const tracks = {
      ...timeline.tracks,
      [trackId]: {
        ...track,
        clipIds: [...track.clipIds, clip.id],
      },
    }

    // Recalculate duration
    const maxEnd = Object.values(clips).reduce(
      (max, c) => Math.max(max, c.timing.end),
      0
    )

    return {
      success: true,
      timeline: { ...timeline, tracks, clips, duration: maxEnd },
      errors,
    }
  }
}

// =============================================================================
// TimelineIntelligencePanel Component
// =============================================================================
// Displays timeline analysis results, issues, and suggestions.
// Allows one-click application of suggestions and auto-fixes.
// Includes decision tracing, explainability, and replay features.
// =============================================================================

import { useState, useCallback } from 'react'
import { useTimelineStore } from '../store/timelineStore'
import {
  analyzeTimeline,
  generateSuggestions,
  resolveTimelineConflicts,
  autoStackClips,
  compactTimeline,
  type TimelineAnalysisReport,
  type Suggestion,
  type OverlapStrategy,
} from '../intelligence'
import {
  replayAnalysis,
  replaySuggestions,
  replayConflictResolution,
  replayAutoLayout,
  fullReplay,
  explainSuggestion,
  formatExplanationAsText,
  getAllTraces,
  getRecentTraces,
  clearTraces,
  globalRuleTracker,
  type DecisionTrace,
  type Explanation,
} from '../intelligence/trace'

export function TimelineIntelligencePanel() {
  const { timeline, executeCommand } = useTimelineStore()
  const [report, setReport] = useState<TimelineAnalysisReport | null>(null)
  const [suggestions, setSuggestions] = useState<Suggestion[]>([])
  const [isAnalyzing, setIsAnalyzing] = useState(false)
  const [selectedStrategy, setSelectedStrategy] = useState<OverlapStrategy>('SHIFT_RIGHT')

  // Trace state
  const [showTrace, setShowTrace] = useState(false)
  const [traces, setTraces] = useState<DecisionTrace[]>([])
  const [selectedTrace, setSelectedTrace] = useState<DecisionTrace | null>(null)
  const [explanation, setExplanation] = useState<Explanation | null>(null)
  const [showExplanation, setShowExplanation] = useState(false)

  const handleAnalyze = useCallback(() => {
    setIsAnalyzing(true)

    // Use replay to get trace
    const { report: analysisReport, trace } = replayAnalysis(timeline)
    const { suggestions: generatedSuggestions } = replaySuggestions(timeline)

    setReport(analysisReport)
    setSuggestions(generatedSuggestions)
    setTraces(getRecentTraces(10))
    setIsAnalyzing(false)
  }, [timeline])

  const handleApplySuggestion = useCallback(
    (suggestion: Suggestion) => {
      if (suggestion.command) {
        executeCommand(suggestion.command)
        handleAnalyze()
      }
    },
    [executeCommand, handleAnalyze]
  )

  const handleExplainSuggestion = useCallback(
    (suggestion: Suggestion) => {
      const recentTraces = getRecentTraces(5)
      const suggestTrace = recentTraces.find(t => t.summary.includes('Suggestion'))

      if (suggestTrace) {
        const exp = explainSuggestion(suggestion.id, suggestTrace)
        setExplanation(exp)
        setShowExplanation(true)
      }
    },
    []
  )

  const handleResolveAllConflicts = useCallback(() => {
    const { result, trace } = replayConflictResolution(timeline, selectedStrategy)

    for (const command of result.commands) {
      executeCommand(command)
    }

    setTraces(getRecentTraces(10))
    setTimeout(handleAnalyze, 100)
  }, [timeline, selectedStrategy, executeCommand, handleAnalyze])

  const handleAutoStack = useCallback(() => {
    const { result } = replayAutoLayout(timeline, 'stack')

    for (const command of result.commands) {
      executeCommand(command)
    }

    setTraces(getRecentTraces(10))
    setTimeout(handleAnalyze, 100)
  }, [timeline, executeCommand, handleAnalyze])

  const handleCompact = useCallback(() => {
    const { result } = replayAutoLayout(timeline, 'compact')

    for (const command of result.commands) {
      executeCommand(command)
    }

    setTraces(getRecentTraces(10))
    setTimeout(handleAnalyze, 100)
  }, [timeline, executeCommand, handleAnalyze])

  const handleFullReplay = useCallback(() => {
    const replayResult = fullReplay(timeline)
    setTraces(getRecentTraces(10))
    handleAnalyze()
  }, [timeline, handleAnalyze])

  const handleClearTraces = useCallback(() => {
    clearTraces()
    globalRuleTracker.clear()
    setTraces([])
    setSelectedTrace(null)
  }, [])

  const applicableSuggestions = suggestions.filter(s => s.autoApplicable && s.command)

  return (
    <div className="rounded-lg border border-gray-800 bg-gray-950 overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-gray-800 bg-gray-900">
        <span className="text-xs font-medium text-gray-400">Timeline Intelligence</span>
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => setShowTrace(!showTrace)}
            className={`rounded px-2 py-1 text-xs transition-colors ${
              showTrace ? 'bg-purple-600 text-white' : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
            }`}
            title="Toggle Trace View"
          >
            Trace
          </button>
          <button
            type="button"
            onClick={handleAnalyze}
            disabled={isAnalyzing}
            className="rounded bg-blue-600 px-2 py-1 text-xs font-medium text-white hover:bg-blue-500 disabled:opacity-50 transition-colors"
          >
            {isAnalyzing ? 'Analyzing...' : 'Analyze'}
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="max-h-[500px] overflow-y-auto">
        {/* Quick Actions */}
        <div className="px-3 py-2 border-b border-gray-800">
          <div className="text-[10px] text-gray-500 uppercase mb-2">Quick Actions</div>
          <div className="flex flex-wrap gap-1">
            <ActionButton
              label="Auto-Stack"
              onClick={handleAutoStack}
              disabled={!report || report.issues.filter(i => i.type === 'OVERLAP').length === 0}
            />
            <ActionButton
              label="Compact"
              onClick={handleCompact}
              disabled={!report}
            />
            <ActionButton
              label="Full Replay"
              onClick={handleFullReplay}
              disabled={false}
            />
            <div className="flex items-center gap-1">
              <select
                value={selectedStrategy}
                onChange={(e) => setSelectedStrategy(e.target.value as OverlapStrategy)}
                className="rounded bg-gray-800 px-2 py-1 text-xs text-gray-300 border border-gray-700"
              >
                <option value="SHIFT_RIGHT">Shift Right</option>
                <option value="TRIM_CLIP">Trim Clip</option>
              </select>
              <ActionButton
                label="Resolve All"
                onClick={handleResolveAllConflicts}
                disabled={!report || report.issues.filter(i => i.type === 'OVERLAP').length === 0}
              />
            </div>
          </div>
        </div>

        {/* Explanation Panel */}
        {showExplanation && explanation && (
          <div className="px-3 py-2 border-b border-gray-800 bg-gray-900/50">
            <div className="flex items-center justify-between mb-2">
              <div className="text-[10px] text-purple-400 uppercase">Explanation</div>
              <button
                type="button"
                onClick={() => setShowExplanation(false)}
                className="text-gray-500 hover:text-gray-300 text-xs"
              >
                Close
              </button>
            </div>
            <div className="text-xs text-gray-300 whitespace-pre-wrap">
              {formatExplanationAsText(explanation)}
            </div>
          </div>
        )}

        {/* Trace Panel */}
        {showTrace && (
          <div className="px-3 py-2 border-b border-gray-800">
            <div className="flex items-center justify-between mb-2">
              <div className="text-[10px] text-purple-400 uppercase">
                Decision Traces ({traces.length})
              </div>
              <button
                type="button"
                onClick={handleClearTraces}
                className="text-[10px] text-gray-500 hover:text-gray-300"
              >
                Clear
              </button>
            </div>
            <div className="space-y-1 max-h-40 overflow-y-auto">
              {traces.map(trace => (
                <TraceItem
                  key={trace.id}
                  trace={trace}
                  isSelected={selectedTrace?.id === trace.id}
                  onSelect={() => setSelectedTrace(trace)}
                />
              ))}
              {traces.length === 0 && (
                <div className="text-xs text-gray-600 text-center py-2">
                  No traces recorded
                </div>
              )}
            </div>
          </div>
        )}

        {/* Health Score */}
        {report && (
          <div className="px-3 py-2 border-b border-gray-800">
            <div className="text-[10px] text-gray-500 uppercase mb-1">Health Score</div>
            <HealthBar score={report.overallHealth} />
          </div>
        )}

        {/* Issues */}
        {report && report.issues.length > 0 && (
          <div className="px-3 py-2 border-b border-gray-800">
            <div className="text-[10px] text-gray-500 uppercase mb-2">
              Issues ({report.issues.length})
            </div>
            <div className="space-y-1">
              {report.issues.map(issue => (
                <IssueItem key={issue.id} issue={issue} />
              ))}
            </div>
          </div>
        )}

        {/* Warnings */}
        {report && report.warnings.length > 0 && (
          <div className="px-3 py-2 border-b border-gray-800">
            <div className="text-[10px] text-gray-500 uppercase mb-2">
              Warnings ({report.warnings.length})
            </div>
            <div className="space-y-1">
              {report.warnings.map(warning => (
                <IssueItem key={warning.id} issue={warning} />
              ))}
            </div>
          </div>
        )}

        {/* Suggestions */}
        {applicableSuggestions.length > 0 && (
          <div className="px-3 py-2 border-b border-gray-800">
            <div className="text-[10px] text-gray-500 uppercase mb-2">
              Suggestions ({applicableSuggestions.length})
            </div>
            <div className="space-y-1">
              {applicableSuggestions.map(suggestion => (
                <SuggestionItem
                  key={suggestion.id}
                  suggestion={suggestion}
                  onApply={() => handleApplySuggestion(suggestion)}
                  onExplain={() => handleExplainSuggestion(suggestion)}
                />
              ))}
            </div>
          </div>
        )}

        {/* Track Density */}
        {report && report.trackDensity.length > 0 && (
          <div className="px-3 py-2">
            <div className="text-[10px] text-gray-500 uppercase mb-2">Track Density</div>
            <div className="space-y-1">
              {report.trackDensity.map(density => (
                <TrackDensityItem key={density.trackId} density={density} />
              ))}
            </div>
          </div>
        )}

        {/* Empty State */}
        {!report && (
          <div className="px-3 py-8 text-center text-xs text-gray-600">
            Click "Analyze" to inspect your timeline
          </div>
        )}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Sub-Components
// ---------------------------------------------------------------------------

function ActionButton({
  label,
  onClick,
  disabled,
}: {
  label: string
  onClick: () => void
  disabled: boolean
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      className="rounded bg-gray-800 px-2 py-1 text-xs text-gray-300 hover:bg-gray-700 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
    >
      {label}
    </button>
  )
}

function HealthBar({ score }: { score: number }) {
  const color =
    score >= 80 ? 'bg-green-500' :
    score >= 50 ? 'bg-yellow-500' :
    'bg-red-500'

  return (
    <div className="flex items-center gap-2">
      <div className="flex-1 h-2 bg-gray-800 rounded-full overflow-hidden">
        <div
          className={`h-full ${color} transition-all`}
          style={{ width: `${score}%` }}
        />
      </div>
      <span className="text-xs text-gray-400">{score}%</span>
    </div>
  )
}

function IssueItem({ issue }: { issue: { severity: string; message: string; type: string } }) {
  const icon =
    issue.severity === 'error' ? '!' :
    issue.severity === 'warning' ? '⚠' :
    'i'

  const iconColor =
    issue.severity === 'error' ? 'text-red-400' :
    issue.severity === 'warning' ? 'text-yellow-400' :
    'text-blue-400'

  return (
    <div className="flex items-start gap-2 text-xs">
      <span className={`${iconColor} flex-shrink-0`}>{icon}</span>
      <span className="text-gray-300">{issue.message}</span>
    </div>
  )
}

function SuggestionItem({
  suggestion,
  onApply,
  onExplain,
}: {
  suggestion: Suggestion
  onApply: () => void
  onExplain: () => void
}) {
  const confidenceColor =
    suggestion.confidence === 'high' ? 'text-green-400' :
    suggestion.confidence === 'medium' ? 'text-yellow-400' :
    'text-gray-400'

  return (
    <div className="flex items-start gap-2 text-xs">
      <div className="flex-1">
        <div className="flex items-center gap-2">
          <span className="text-gray-200">{suggestion.title}</span>
          <span className={`${confidenceColor} text-[10px]`}>
            {suggestion.confidence}
          </span>
        </div>
        <div className="text-gray-500">{suggestion.description}</div>
      </div>
      <div className="flex items-center gap-1 flex-shrink-0">
        <button
          type="button"
          onClick={onExplain}
          className="rounded bg-purple-600 px-2 py-0.5 text-[10px] text-white hover:bg-purple-500 transition-colors"
          title="Explain this suggestion"
        >
          ?
        </button>
        {suggestion.autoApplicable && (
          <button
            type="button"
            onClick={onApply}
            className="rounded bg-blue-600 px-2 py-0.5 text-[10px] text-white hover:bg-blue-500 transition-colors"
          >
            Apply
          </button>
        )}
      </div>
    </div>
  )
}

function TraceItem({
  trace,
  isSelected,
  onSelect,
}: {
  trace: DecisionTrace
  isSelected: boolean
  onSelect: () => void
}) {
  const nodeCount = Object.keys(trace.nodes).length
  const duration = trace.completedAt ? trace.completedAt - trace.startedAt : 0

  return (
    <button
      type="button"
      onClick={onSelect}
      className={`w-full text-left rounded px-2 py-1 text-xs transition-colors ${
        isSelected ? 'bg-purple-900/50 border border-purple-700' : 'bg-gray-900 hover:bg-gray-800'
      }`}
    >
      <div className="flex items-center justify-between">
        <span className="text-gray-300 truncate">{trace.summary}</span>
        <span className="text-gray-600 text-[10px] ml-2">{nodeCount} nodes</span>
      </div>
      <div className="text-gray-600 text-[10px]">
        {duration}ms · {new Date(trace.startedAt).toLocaleTimeString()}
      </div>
    </button>
  )
}

function TrackDensityItem({
  density,
}: {
  density: { trackName: string; clipCount: number; coverage: number }
}) {
  return (
    <div className="flex items-center gap-2 text-xs">
      <span className="text-gray-300 w-24 truncate">{density.trackName}</span>
      <div className="flex-1 h-1.5 bg-gray-800 rounded-full overflow-hidden">
        <div
          className="h-full bg-blue-500"
          style={{ width: `${Math.min(density.coverage * 100, 100)}%` }}
        />
      </div>
      <span className="text-gray-500 w-16 text-right">
        {density.clipCount} clips
      </span>
    </div>
  )
}

// =============================================================================
// TrackView Component
// =============================================================================
// Renders a single track row in the timeline.
// Contains clip blocks and track header with controls.
// Supports drop zones for drag and drop.
// =============================================================================

import { useDroppable } from '@dnd-kit/core'
import type { TimelineTrack, TrackLayout } from '../model/timeline'
import { TRACK_TYPE_COLORS } from '../model/timeline'
import { useTimelineStore } from '../store/timelineStore'
import { ClipBlock } from './ClipBlock'

interface TrackViewProps {
  track: TimelineTrack
  layout: TrackLayout
  pixelsPerSecond: number
  onTrimStart?: (clipId: string, side: 'start' | 'end', clientX: number) => void
}

export function TrackView({ track, layout, pixelsPerSecond, onTrimStart }: TrackViewProps) {
  const { selectedClipId, setSelectedClip, selectedTrackId, setSelectedTrack } = useTimelineStore()
  const clips = useTimelineStore((state) => state.getTrackClips(track.id))
  const isSelected = selectedTrackId === track.id
  const trackColor = TRACK_TYPE_COLORS[track.type]

  const { setNodeRef, isOver } = useDroppable({
    id: track.id,
    data: { track },
  })

  return (
    <div
      className={`flex border-b border-gray-800 ${isSelected ? 'bg-gray-800/50' : ''}`}
      onClick={() => setSelectedTrack(track.id)}
    >
      {/* Track Header */}
      <div
        className="w-40 flex-shrink-0 flex items-center gap-2 px-3 py-2 border-r border-gray-800 cursor-pointer hover:bg-gray-800/50"
        onClick={(e) => {
          e.stopPropagation()
          setSelectedTrack(track.id)
        }}
      >
        <div
          className="w-3 h-3 rounded-full flex-shrink-0"
          style={{ backgroundColor: trackColor }}
        />
        <div className="min-w-0">
          <div className="text-xs font-medium text-gray-200 truncate">
            {track.name}
          </div>
          <div className="text-[10px] text-gray-500 uppercase">
            {track.type}
          </div>
        </div>
        <div className="ml-auto flex items-center gap-1">
          {track.muted && (
            <span className="text-[10px] text-red-400">M</span>
          )}
          {track.locked && (
            <span className="text-[10px] text-yellow-400">L</span>
          )}
        </div>
      </div>

      {/* Track Body (clips) - Drop zone */}
      <div
        ref={setNodeRef}
        className="relative flex-1 transition-colors"
        style={{
          height: `${track.height}px`,
          minHeight: `${track.height}px`,
          backgroundColor: isOver ? 'rgba(59, 130, 246, 0.1)' : undefined,
        }}
      >
        {clips.map((clip) => (
          <ClipBlock
            key={clip.id}
            clip={clip}
            pixelsPerSecond={pixelsPerSecond}
            isSelected={selectedClipId === clip.id}
            onSelect={setSelectedClip}
            onTrimStart={onTrimStart}
          />
        ))}

        {/* Drop indicator */}
        {isOver && (
          <div className="absolute inset-0 border-2 border-blue-500/50 rounded pointer-events-none" />
        )}
      </div>
    </div>
  )
}

// =============================================================================
// Snap System
// =============================================================================
// Provides snap-to-grid and snap-to-adjacent-clip functionality.
// Used by drag and trim operations to align clips precisely.
// =============================================================================

import type { TimelineClip, TimelineCanvasState } from '../model/timeline'

// ---------------------------------------------------------------------------
// Snap Configuration
// ---------------------------------------------------------------------------
export interface SnapConfig {
  readonly enabled: boolean
  readonly gridSnap: boolean
  readonly clipSnap: boolean
  readonly threshold: number  // seconds - snap activates within this distance
}

export const DEFAULT_SNAP_CONFIG: SnapConfig = {
  enabled: true,
  gridSnap: true,
  clipSnap: true,
  threshold: 0.1,
}

// ---------------------------------------------------------------------------
// Snap Target
// ---------------------------------------------------------------------------
export interface SnapTarget {
  readonly time: number
  readonly type: 'grid' | 'clip-start' | 'clip-end'
  readonly sourceId?: string  // clip id for clip snaps
}

// ---------------------------------------------------------------------------
// Snap Result
// ---------------------------------------------------------------------------
export interface SnapResult {
  readonly snappedTime: number
  readonly snapped: boolean
  readonly target?: SnapTarget
}

// ---------------------------------------------------------------------------
// Grid Snap Points
// ---------------------------------------------------------------------------
function getGridSnapPoints(duration: number, zoomLevel: number): number[] {
  const points: number[] = []
  // Grid interval based on zoom: 1x=1s, 2x=0.5s, 4x=0.25s
  const interval = 1 / zoomLevel

  for (let t = 0; t <= duration + interval; t += interval) {
    points.push(Math.round(t * 1000) / 1000) // avoid floating point issues
  }
  return points
}

// ---------------------------------------------------------------------------
// Clip Snap Points
// ---------------------------------------------------------------------------
function getClipSnapPoints(
  clips: Record<string, TimelineClip>,
  excludeClipId?: string
): SnapTarget[] {
  const targets: SnapTarget[] = []

  for (const clip of Object.values(clips)) {
    if (clip.id === excludeClipId) continue

    targets.push({
      time: clip.timing.start,
      type: 'clip-start',
      sourceId: clip.id,
    })
    targets.push({
      time: clip.timing.end,
      type: 'clip-end',
      sourceId: clip.id,
    })
  }

  return targets
}

// ---------------------------------------------------------------------------
// Find Nearest Snap
// ---------------------------------------------------------------------------
export function findNearestSnap(
  time: number,
  timeline: TimelineCanvasState,
  zoomLevel: number,
  excludeClipId?: string,
  config: SnapConfig = DEFAULT_SNAP_CONFIG
): SnapResult {
  if (!config.enabled) {
    return { snappedTime: time, snapped: false }
  }

  const allTargets: SnapTarget[] = []

  // Grid snap points
  if (config.gridSnap) {
    const gridPoints = getGridSnapPoints(timeline.duration, zoomLevel)
    for (const t of gridPoints) {
      allTargets.push({ time: t, type: 'grid' })
    }
  }

  // Clip snap points
  if (config.clipSnap) {
    const clipTargets = getClipSnapPoints(timeline.clips, excludeClipId)
    allTargets.push(...clipTargets)
  }

  // Find nearest target within threshold
  let nearestTarget: SnapTarget | undefined
  let nearestDist = config.threshold

  for (const target of allTargets) {
    const dist = Math.abs(time - target.time)
    if (dist < nearestDist) {
      nearestDist = dist
      nearestTarget = target
    }
  }

  if (nearestTarget) {
    return {
      snappedTime: nearestTarget.time,
      snapped: true,
      target: nearestTarget,
    }
  }

  return { snappedTime: time, snapped: false }
}

// ---------------------------------------------------------------------------
// Snap for Trim Operations
// ---------------------------------------------------------------------------
export function findTrimSnap(
  time: number,
  timeline: TimelineCanvasState,
  zoomLevel: number,
  clipId: string,
  trimSide: 'start' | 'end',
  config: SnapConfig = DEFAULT_SNAP_CONFIG
): SnapResult {
  // For trim, we only snap to the opposite edge of the same clip
  // and to other clip edges
  const clip = timeline.clips[clipId]
  if (!clip) {
    return { snappedTime: time, snapped: false }
  }

  // Add the opposite edge as a snap target
  const additionalTargets: SnapTarget[] = []
  if (trimSide === 'start') {
    // When trimming start, snap to end edge is not useful
    // But we should not snap to own start
  } else {
    // When trimming end, snap to start edge is not useful
  }

  return findNearestSnap(time, timeline, zoomLevel, clipId, config)
}

// =============================================================================
// Timeline Mutation Engine
// =============================================================================
// Central engine for all timeline mutations.
// All changes to timeline state MUST go through this engine.
// UI cannot directly mutate Zustand state.
//
// Rules:
// - Validates all mutations before applying
// - Resolves overlaps automatically
// - Enforces track constraints
// - Maintains normalized state integrity
// =============================================================================

import type {
  TimelineCanvasState,
  TimelineClip,
  TimelineTrack,
} from '../model/timeline'
import { findNearestSnap, type SnapConfig, DEFAULT_SNAP_CONFIG } from './snap'

// ---------------------------------------------------------------------------
// Mutation Result
// ---------------------------------------------------------------------------
export interface MutationResult {
  readonly success: boolean
  readonly timeline: TimelineCanvasState
  readonly errors: readonly string[]
}

// ---------------------------------------------------------------------------
// Clip Move Operation
// ---------------------------------------------------------------------------
export interface ClipMoveOperation {
  readonly clipId: string
  readonly newStart: number
  readonly newTrackId: string
  readonly snapConfig?: SnapConfig
  readonly zoomLevel?: number
}

// ---------------------------------------------------------------------------
// Clip Trim Operation
// ---------------------------------------------------------------------------
export interface ClipTrimOperation {
  readonly clipId: string
  readonly side: 'start' | 'end'
  readonly newTime: number
  readonly snapConfig?: SnapConfig
  readonly zoomLevel?: number
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------
const MIN_CLIP_DURATION = 0.1 // seconds

// ---------------------------------------------------------------------------
// Validation: check if timeline state is valid
// ---------------------------------------------------------------------------
export function validateTimeline(timeline: TimelineCanvasState): string[] {
  const errors: string[] = []

  // Check all track references
  for (const track of Object.values(timeline.tracks)) {
    for (const clipId of track.clipIds) {
      if (!timeline.clips[clipId]) {
        errors.push(`Track "${track.name}" references missing clip "${clipId}"`)
      }
    }
  }

  // Check all clip track references
  for (const clip of Object.values(timeline.clips)) {
    if (!timeline.tracks[clip.trackId]) {
      errors.push(`Clip "${clip.name}" references missing track "${clip.trackId}"`)
    }
    if (clip.timing.duration < 0) {
      errors.push(`Clip "${clip.name}" has negative duration`)
    }
    if (clip.timing.end < clip.timing.start) {
      errors.push(`Clip "${clip.name}" has end before start`)
    }
  }

  // Check track order references
  for (const trackId of timeline.trackOrder) {
    if (!timeline.tracks[trackId]) {
      errors.push(`Track order references missing track "${trackId}"`)
    }
  }

  return errors
}

// ---------------------------------------------------------------------------
// Validation: check for overlapping clips on same track
// ---------------------------------------------------------------------------
export function findOverlaps(timeline: TimelineCanvasState): Array<{
  trackId: string
  clipA: TimelineClip
  clipB: TimelineClip
}> {
  const overlaps: Array<{
    trackId: string
    clipA: TimelineClip
    clipB: TimelineClip
  }> = []

  for (const track of Object.values(timeline.tracks)) {
    const clips = track.clipIds
      .map((id) => timeline.clips[id])
      .filter((c): c is TimelineClip => c != null)
      .sort((a, b) => a.timing.start - b.timing.start)

    for (let i = 1; i < clips.length; i++) {
      if (clips[i].timing.start < clips[i - 1].timing.end) {
        overlaps.push({
          trackId: track.id,
          clipA: clips[i - 1],
          clipB: clips[i],
        })
      }
    }
  }

  return overlaps
}

// ---------------------------------------------------------------------------
// Resolve overlaps by pushing clips right
// ---------------------------------------------------------------------------
export function resolveOverlaps(timeline: TimelineCanvasState): TimelineCanvasState {
  const result = { ...timeline, clips: { ...timeline.clips } }
  const tracks = { ...timeline.tracks }

  for (const track of Object.values(tracks)) {
    const clips = track.clipIds
      .map((id) => result.clips[id])
      .filter((c): c is TimelineClip => c != null)
      .sort((a, b) => a.timing.start - b.timing.start)

    let lastEnd = 0
    for (const clip of clips) {
      if (clip.timing.start < lastEnd) {
        const duration = clip.timing.duration
        const newClip: TimelineClip = {
          ...clip,
          timing: {
            start: lastEnd,
            end: lastEnd + duration,
            duration,
          },
        }
        result.clips[clip.id] = newClip
      }
      lastEnd = result.clips[clip.id].timing.end
    }
  }

  // Recalculate duration
  const maxEnd = Object.values(result.clips).reduce(
    (max, c) => Math.max(max, c.timing.end),
    0
  )
  result.duration = maxEnd
  result.tracks = tracks

  return result
}

// ---------------------------------------------------------------------------
// Apply clip move
// ---------------------------------------------------------------------------
export function applyClipMove(
  timeline: TimelineCanvasState,
  operation: ClipMoveOperation
): MutationResult {
  const { clipId, newStart, newTrackId, snapConfig, zoomLevel } = operation
  const errors: string[] = []

  // Validate clip exists
  const clip = timeline.clips[clipId]
  if (!clip) {
    return { success: false, timeline, errors: [`Clip "${clipId}" not found`] }
  }

  // Validate target track exists
  const targetTrack = timeline.tracks[newTrackId]
  if (!targetTrack) {
    return { success: false, timeline, errors: [`Track "${newTrackId}" not found`] }
  }

  // Check track is not locked
  if (targetTrack.locked) {
    return { success: false, timeline, errors: [`Track "${targetTrack.name}" is locked`] }
  }

  // Apply snap if configured
  let finalStart = newStart
  if (snapConfig?.enabled && zoomLevel) {
    const snapResult = findNearestSnap(
      newStart,
      timeline,
      zoomLevel,
      clipId,
      snapConfig
    )
    finalStart = snapResult.snappedTime
  }

  // Ensure clip doesn't go negative
  finalStart = Math.max(0, finalStart)

  const duration = clip.timing.duration
  const newEnd = finalStart + duration

  // Update clip
  const updatedClip: TimelineClip = {
    ...clip,
    trackId: newTrackId,
    timing: {
      start: finalStart,
      end: newEnd,
      duration,
    },
  }

  // Update tracks
  const tracks = { ...timeline.tracks }

  // Remove from old track
  if (clip.trackId !== newTrackId) {
    const oldTrack = tracks[clip.trackId]
    if (oldTrack) {
      tracks[clip.trackId] = {
        ...oldTrack,
        clipIds: oldTrack.clipIds.filter((id) => id !== clipId),
      }
    }

    // Add to new track
    tracks[newTrackId] = {
      ...targetTrack,
      clipIds: [...targetTrack.clipIds, clipId],
    }
  }

  // Update clips
  const clips = { ...timeline.clips, [clipId]: updatedClip }

  // Recalculate duration
  const maxEnd = Object.values(clips).reduce(
    (max, c) => Math.max(max, c.timing.end),
    0
  )

  const newTimeline: TimelineCanvasState = {
    ...timeline,
    tracks,
    clips,
    duration: maxEnd,
  }

  // Validate result
  const validationErrors = validateTimeline(newTimeline)
  if (validationErrors.length > 0) {
    return { success: false, timeline, errors: validationErrors }
  }

  return { success: true, timeline: newTimeline, errors }
}

// ---------------------------------------------------------------------------
// Apply clip trim
// ---------------------------------------------------------------------------
export function applyClipTrim(
  timeline: TimelineCanvasState,
  operation: ClipTrimOperation
): MutationResult {
  const { clipId, side, newTime, snapConfig, zoomLevel } = operation
  const errors: string[] = []

  // Validate clip exists
  const clip = timeline.clips[clipId]
  if (!clip) {
    return { success: false, timeline, errors: [`Clip "${clipId}" not found`] }
  }

  // Check track is not locked
  const track = timeline.tracks[clip.trackId]
  if (track?.locked) {
    return { success: false, timeline, errors: [`Track "${track.name}" is locked`] }
  }

  // Apply snap if configured
  let finalTime = newTime
  if (snapConfig?.enabled && zoomLevel) {
    const snapResult = findNearestSnap(
      newTime,
      timeline,
      zoomLevel,
      clipId,
      snapConfig
    )
    finalTime = snapResult.snappedTime
  }

  let newStart = clip.timing.start
  let newEnd = clip.timing.end
  let newDuration = clip.timing.duration

  if (side === 'start') {
    // Trim start: cannot go past end
    finalTime = Math.min(finalTime, clip.timing.end - MIN_CLIP_DURATION)
    finalTime = Math.max(0, finalTime)
    newStart = finalTime
    newDuration = newEnd - newStart
  } else {
    // Trim end: cannot go before start
    finalTime = Math.max(finalTime, clip.timing.start + MIN_CLIP_DURATION)
    newEnd = finalTime
    newDuration = newEnd - newStart
  }

  // Update clip
  const updatedClip: TimelineClip = {
    ...clip,
    timing: {
      start: newStart,
      end: newEnd,
      duration: newDuration,
    },
  }

  // Update clips
  const clips = { ...timeline.clips, [clipId]: updatedClip }

  // Recalculate duration
  const maxEnd = Object.values(clips).reduce(
    (max, c) => Math.max(max, c.timing.end),
    0
  )

  const newTimeline: TimelineCanvasState = {
    ...timeline,
    clips,
    duration: maxEnd,
  }

  // Validate result
  const validationErrors = validateTimeline(newTimeline)
  if (validationErrors.length > 0) {
    return { success: false, timeline, errors: validationErrors }
  }

  return { success: true, timeline: newTimeline, errors }
}

// ---------------------------------------------------------------------------
// Validate mutation before applying
// ---------------------------------------------------------------------------
export function validateTimelineMutation(
  timeline: TimelineCanvasState,
  clipId: string,
  newStart: number,
  newDuration: number,
  newTrackId?: string
): string[] {
  const errors: string[] = []

  const clip = timeline.clips[clipId]
  if (!clip) {
    errors.push(`Clip "${clipId}" not found`)
    return errors
  }

  const trackId = newTrackId ?? clip.trackId
  const track = timeline.tracks[trackId]
  if (!track) {
    errors.push(`Track "${trackId}" not found`)
    return errors
  }

  if (track.locked) {
    errors.push(`Track "${track.name}" is locked`)
  }

  if (newDuration < MIN_CLIP_DURATION) {
    errors.push(`Duration must be at least ${MIN_CLIP_DURATION}s`)
  }

  if (newStart < 0) {
    errors.push('Start time cannot be negative')
  }

  // Check for overlaps with other clips on target track
  const otherClips = track.clipIds
    .filter((id) => id !== clipId)
    .map((id) => timeline.clips[id])
    .filter((c): c is TimelineClip => c != null)

  const newEnd = newStart + newDuration
  for (const other of otherClips) {
    if (newStart < other.timing.end && newEnd > other.timing.start) {
      errors.push(`Would overlap with clip "${other.name}"`)
    }
  }

  return errors
}

// =============================================================================
// Auto Layout Engine
// =============================================================================
// Automatically optimizes timeline layout.
// Generates commands for layout improvements without direct mutation.
// =============================================================================

import type { TimelineCanvasState, TimelineClip, TimelineTrack } from '../model/timeline'
import type { TimelineCommand } from '../commands/types'
import { createMetadata } from '../commands/types'
import { MoveClipCommand } from '../commands/commands/MoveClipCommand'
import { DeleteClipCommand } from '../commands/commands/DeleteClipCommand'

// ---------------------------------------------------------------------------
// Layout Result
// ---------------------------------------------------------------------------
export interface LayoutResult {
  readonly commands: readonly TimelineCommand[]
  readonly description: string
  readonly affectedClips: number
}

// ---------------------------------------------------------------------------
// Auto Stack Clips
// ---------------------------------------------------------------------------
// Shifts clips right to eliminate overlaps on each track.
export function autoStackClips(timeline: TimelineCanvasState): LayoutResult {
  const commands: TimelineCommand[] = []
  const metadata = createMetadata('Auto-stack clips to remove overlaps', 'system')

  for (const track of Object.values(timeline.tracks)) {
    if (track.locked) continue

    const clips = getTrackClipsSorted(timeline, track.id)
    let lastEnd = 0

    for (const clip of clips) {
      if (clip.timing.start < lastEnd) {
        // Need to shift this clip right
        const command = new MoveClipCommand(
          {
            clipId: clip.id,
            fromStart: clip.timing.start,
            fromTrackId: clip.trackId,
            toStart: lastEnd,
            toTrackId: clip.trackId,
          },
          metadata
        )
        commands.push(command)
      }
      lastEnd = Math.max(lastEnd, clip.timing.end)
    }
  }

  return {
    commands,
    description: `Auto-stacked ${commands.length} clips to remove overlaps`,
    affectedClips: commands.length,
  }
}

// ---------------------------------------------------------------------------
// Compact Timeline
// ---------------------------------------------------------------------------
// Removes gaps between clips, compacting the timeline.
export function compactTimeline(timeline: TimelineCanvasState, threshold: number = 0.5): LayoutResult {
  const commands: TimelineCommand[] = []
  const metadata = createMetadata('Compact timeline by removing gaps', 'system')

  for (const track of Object.values(timeline.tracks)) {
    if (track.locked) continue

    const clips = getTrackClipsSorted(timeline, track.id)
    if (clips.length < 2) continue

    let shiftAmount = 0
    let lastEnd = clips[0].timing.end

    for (let i = 1; i < clips.length; i++) {
      const clip = clips[i]
      const gap = clip.timing.start - lastEnd

      if (gap > threshold) {
        shiftAmount += gap
      }

      if (shiftAmount > 0) {
        const newStart = clip.timing.start - shiftAmount
        const command = new MoveClipCommand(
          {
            clipId: clip.id,
            fromStart: clip.timing.start,
            fromTrackId: clip.trackId,
            toStart: Math.max(0, newStart),
            toTrackId: clip.trackId,
          },
          metadata
        )
        commands.push(command)
      }

      lastEnd = clip.timing.end
    }
  }

  return {
    commands,
    description: `Compacted timeline by removing ${commands.length} gaps`,
    affectedClips: commands.length,
  }
}

// ---------------------------------------------------------------------------
// Normalize Track Distribution
// ---------------------------------------------------------------------------
// Moves clips to fill empty tracks and balance load.
export function normalizeTrackDistribution(timeline: TimelineCanvasState): LayoutResult {
  const commands: TimelineCommand[] = []
  const metadata = createMetadata('Normalize track distribution', 'system')

  const videoTracks = Object.values(timeline.tracks)
    .filter(t => t.type === 'video' && !t.locked)
    .sort((a, b) => a.clipIds.length - b.clipIds.length)

  if (videoTracks.length < 2) return { commands, description: 'Not enough tracks to normalize', affectedClips: 0 }

  const mostLoaded = videoTracks[videoTracks.length - 1]
  const leastLoaded = videoTracks[0]

  if (mostLoaded.clipIds.length - leastLoaded.clipIds.length < 2) {
    return { commands, description: 'Tracks are already balanced', affectedClips: 0 }
  }

  // Move half of the clips from the most loaded to the least loaded
  const clipsToMove = getTrackClipsSorted(timeline, mostLoaded.id)
    .slice(Math.floor(mostLoaded.clipIds.length / 2))

  for (const clip of clipsToMove) {
    const command = new MoveClipCommand(
      {
        clipId: clip.id,
        fromStart: clip.timing.start,
        fromTrackId: clip.trackId,
        toStart: clip.timing.start,
        toTrackId: leastLoaded.id,
      },
      metadata
    )
    commands.push(command)
  }

  return {
    commands,
    description: `Moved ${commands.length} clips to balance tracks`,
    affectedClips: commands.length,
  }
}

// ---------------------------------------------------------------------------
// Balance Track Load
// ---------------------------------------------------------------------------
// Distributes clips evenly across tracks of the same type.
export function balanceTrackLoad(timeline: TimelineCanvasState, trackType: TimelineTrack['type']): LayoutResult {
  const commands: TimelineCommand[] = []
  const metadata = createMetadata(`Balance ${trackType} track load`, 'system')

  const tracks = Object.values(timeline.tracks)
    .filter(t => t.type === trackType && !t.locked)
    .sort((a, b) => {
      const orderA = timeline.layouts[a.id]?.order ?? 0
      const orderB = timeline.layouts[b.id]?.order ?? 0
      return orderA - orderB
    })

  if (tracks.length < 2) return { commands, description: 'Not enough tracks to balance', affectedClips: 0 }

  // Collect all clips from these tracks
  const allClips: TimelineClip[] = []
  for (const track of tracks) {
    allClips.push(...getTrackClipsSorted(timeline, track.id))
  }

  // Sort clips by start time
  allClips.sort((a, b) => a.timing.start - b.timing.start)

  // Distribute clips round-robin across tracks
  for (let i = 0; i < allClips.length; i++) {
    const clip = allClips[i]
    const targetTrack = tracks[i % tracks.length]

    if (clip.trackId !== targetTrack.id) {
      const command = new MoveClipCommand(
        {
          clipId: clip.id,
          fromStart: clip.timing.start,
          fromTrackId: clip.trackId,
          toStart: clip.timing.start,
          toTrackId: targetTrack.id,
        },
        metadata
      )
      commands.push(command)
    }
  }

  return {
    commands,
    description: `Balanced ${commands.length} clips across ${tracks.length} ${trackType} tracks`,
    affectedClips: commands.length,
  }
}

// ---------------------------------------------------------------------------
// Remove Empty Tracks
// ---------------------------------------------------------------------------
export function removeEmptyTracks(timeline: TimelineCanvasState): LayoutResult {
  const commands: TimelineCommand[] = []
  const metadata = createMetadata('Remove empty tracks', 'system')

  for (const track of Object.values(timeline.tracks)) {
    if (track.clipIds.length === 0) {
      // We don't have a DeleteTrackCommand yet, so we'll just report
      // This would need a new command type
    }
  }

  return {
    commands,
    description: `Found ${commands.length} empty tracks to remove`,
    affectedClips: 0,
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function getTrackClipsSorted(timeline: TimelineCanvasState, trackId: string): TimelineClip[] {
  const track = timeline.tracks[trackId]
  if (!track) return []

  return track.clipIds
    .map(id => timeline.clips[id])
    .filter((c): c is TimelineClip => c != null)
    .sort((a, b) => a.timing.start - b.timing.start)
}

// =============================================================================
// Suggestion Engine
// =============================================================================
// Analyzes timeline and generates intelligent editing suggestions.
// Each suggestion includes an optional command for one-click application.
// =============================================================================

import type { TimelineCanvasState, TimelineClip } from '../model/timeline'
import type { TimelineCommand } from '../commands/types'
import { createMetadata } from '../commands/types'
import { MoveClipCommand } from '../commands/commands/MoveClipCommand'
import { TrimClipCommand } from '../commands/commands/TrimClipCommand'
import { AddClipCommand } from '../commands/commands/AddClipCommand'
import { createClip } from '../model/timeline'

// ---------------------------------------------------------------------------
// Suggestion Types
// ---------------------------------------------------------------------------
export type SuggestionType =
  | 'TRIM_OPTIMIZATION'
  | 'TRANSITION_INSERTION'
  | 'CLIP_GROUPING'
  | 'TRACK_REORDERING'
  | 'GAP_FILL'
  | 'DURATION_MATCH'

export type SuggestionConfidence = 'high' | 'medium' | 'low'

export interface Suggestion {
  readonly id: string
  readonly type: SuggestionType
  readonly confidence: SuggestionConfidence
  readonly title: string
  readonly description: string
  readonly clipIds: readonly string[]
  readonly trackIds: readonly string[]
  readonly command: TimelineCommand | null
  readonly autoApplicable: boolean
}

// ---------------------------------------------------------------------------
// Suggestion ID Generator
// ---------------------------------------------------------------------------
let suggestionCounter = 0
function generateSuggestionId(): string {
  return `suggestion-${Date.now()}-${++suggestionCounter}`
}

// ---------------------------------------------------------------------------
// Suggest Trim Optimization
// ---------------------------------------------------------------------------
// Finds clips that could be trimmed to better align with adjacent clips.
export function suggestTrimOptimization(timeline: TimelineCanvasState): Suggestion[] {
  const suggestions: Suggestion[] = []

  for (const track of Object.values(timeline.tracks)) {
    if (track.locked) continue

    const clips = getTrackClipsSorted(timeline, track.id)

    for (let i = 1; i < clips.length; i++) {
      const prev = clips[i - 1]
      const curr = clips[i]
      const gap = curr.timing.start - prev.timing.end

      // If gap is very small (< 0.2s), suggest trimming to align
      if (gap > 0 && gap < 0.2) {
        const command = new TrimClipCommand(
          {
            clipId: prev.id,
            side: 'end',
            fromTime: prev.timing.end,
            toTime: curr.timing.start,
          },
          createMetadata('Trim to align with next clip', 'system')
        )

        suggestions.push({
          id: generateSuggestionId(),
          type: 'TRIM_OPTIMIZATION',
          confidence: 'high',
          title: 'Align clips',
          description: `Trim "${prev.name}" to align with "${curr.name}" (${gap.toFixed(2)}s gap)`,
          clipIds: [prev.id, curr.id],
          trackIds: [track.id],
          command,
          autoApplicable: true,
        })
      }
    }
  }

  return suggestions
}

// ---------------------------------------------------------------------------
// Suggest Transition Insertion
// ---------------------------------------------------------------------------
// Finds points where transitions could be added between clips.
export function suggestTransitionInsertion(timeline: TimelineCanvasState): Suggestion[] {
  const suggestions: Suggestion[] = []

  // Find video tracks
  const videoTracks = Object.values(timeline.tracks).filter(t => t.type === 'video')

  for (const track of videoTracks) {
    if (track.locked) continue

    const clips = getTrackClipsSorted(timeline, track.id)

    for (let i = 1; i < clips.length; i++) {
      const prev = clips[i - 1]
      const curr = clips[i]

      // Check if clips are adjacent (no gap)
      if (Math.abs(prev.timing.end - curr.timing.start) < 0.01) {
        // Check if either clip already has a transition effect
        const hasTransition = prev.effectIds.length > 0 || curr.effectIds.length > 0

        if (!hasTransition) {
          suggestions.push({
            id: generateSuggestionId(),
            type: 'TRANSITION_INSERTION',
            confidence: 'medium',
            title: 'Add transition',
            description: `Add transition between "${prev.name}" and "${curr.name}"`,
            clipIds: [prev.id, curr.id],
            trackIds: [track.id],
            command: null, // Would need a new command type for adding effects
            autoApplicable: false,
          })
        }
      }
    }
  }

  return suggestions
}

// ---------------------------------------------------------------------------
// Suggest Clip Grouping
// ---------------------------------------------------------------------------
// Finds clips that are temporally close and could be grouped.
export function suggestClipGrouping(timeline: TimelineCanvasState): Suggestion[] {
  const suggestions: Suggestion[] = []

  // Find video tracks
  const videoTracks = Object.values(timeline.tracks).filter(t => t.type === 'video')

  for (const track of videoTracks) {
    if (track.locked) continue

    const clips = getTrackClipsSorted(timeline, track.id)
    if (clips.length < 3) continue

    // Find groups of clips with small gaps
    let groupStart = 0
    let groupSize = 1

    for (let i = 1; i < clips.length; i++) {
      const gap = clips[i].timing.start - clips[i - 1].timing.end

      if (gap < 1.0) {
        groupSize++
      } else {
        if (groupSize >= 3) {
          const groupClips = clips.slice(groupStart, groupStart + groupSize)
          suggestions.push({
            id: generateSuggestionId(),
            type: 'CLIP_GROUPING',
            confidence: 'low',
            title: 'Group clips',
            description: `Group ${groupSize} clips: ${groupClips.map(c => c.name).join(', ')}`,
            clipIds: groupClips.map(c => c.id),
            trackIds: [track.id],
            command: null, // Would need a grouping command
            autoApplicable: false,
          })
        }
        groupStart = i
        groupSize = 1
      }
    }

    // Check last group
    if (groupSize >= 3) {
      const groupClips = clips.slice(groupStart, groupStart + groupSize)
      suggestions.push({
        id: generateSuggestionId(),
        type: 'CLIP_GROUPING',
        confidence: 'low',
        title: 'Group clips',
        description: `Group ${groupSize} clips: ${groupClips.map(c => c.name).join(', ')}`,
        clipIds: groupClips.map(c => c.id),
        trackIds: [track.id],
        command: null,
        autoApplicable: false,
      })
    }
  }

  return suggestions
}

// ---------------------------------------------------------------------------
// Suggest Track Reordering
// ---------------------------------------------------------------------------
// Suggests moving clips to balance track load.
export function suggestTrackReordering(timeline: TimelineCanvasState): Suggestion[] {
  const suggestions: Suggestion[] = []

  const videoTracks = Object.values(timeline.tracks)
    .filter(t => t.type === 'video' && !t.locked)
    .sort((a, b) => a.clipIds.length - b.clipIds.length)

  if (videoTracks.length < 2) return suggestions

  const mostLoaded = videoTracks[videoTracks.length - 1]
  const leastLoaded = videoTracks[0]

  if (mostLoaded.clipIds.length - leastLoaded.clipIds.length >= 3) {
    const clipsToMove = getTrackClipsSorted(timeline, mostLoaded.id)
      .slice(Math.floor(mostLoaded.clipIds.length * 0.7))

    const commands: TimelineCommand[] = []
    for (const clip of clipsToMove) {
      commands.push(
        new MoveClipCommand(
          {
            clipId: clip.id,
            fromStart: clip.timing.start,
            fromTrackId: clip.trackId,
            toStart: clip.timing.start,
            toTrackId: leastLoaded.id,
          },
          createMetadata('Balance track load', 'system')
        )
      )
    }

    suggestions.push({
      id: generateSuggestionId(),
      type: 'TRACK_REORDERING',
      confidence: 'medium',
      title: 'Balance tracks',
      description: `Move ${clipsToMove.length} clips from "${mostLoaded.name}" to "${leastLoaded.name}"`,
      clipIds: clipsToMove.map(c => c.id),
      trackIds: [mostLoaded.id, leastLoaded.id],
      command: null, // Composite command would be needed
      autoApplicable: false,
    })
  }

  return suggestions
}

// ---------------------------------------------------------------------------
// Suggest Gap Fill
// ---------------------------------------------------------------------------
// Suggests filling gaps with placeholder clips.
export function suggestGapFill(timeline: TimelineCanvasState): Suggestion[] {
  const suggestions: Suggestion[] = []

  const videoTracks = Object.values(timeline.tracks).filter(t => t.type === 'video')

  for (const track of videoTracks) {
    if (track.locked) continue

    const clips = getTrackClipsSorted(timeline, track.id)
    if (clips.length < 2) continue

    for (let i = 1; i < clips.length; i++) {
      const prev = clips[i - 1]
      const curr = clips[i]
      const gap = curr.timing.start - prev.timing.end

      if (gap > 2.0) {
        suggestions.push({
          id: generateSuggestionId(),
          type: 'GAP_FILL',
          confidence: 'low',
          title: 'Fill gap',
          description: `${gap.toFixed(1)}s gap between "${prev.name}" and "${curr.name}"`,
          clipIds: [prev.id, curr.id],
          trackIds: [track.id],
          command: null, // Would need a gap fill command
          autoApplicable: false,
        })
      }
    }
  }

  return suggestions
}

// ---------------------------------------------------------------------------
// Generate All Suggestions
// ---------------------------------------------------------------------------
export function generateSuggestions(timeline: TimelineCanvasState): Suggestion[] {
  return [
    ...suggestTrimOptimization(timeline),
    ...suggestTransitionInsertion(timeline),
    ...suggestClipGrouping(timeline),
    ...suggestTrackReordering(timeline),
    ...suggestGapFill(timeline),
  ].sort((a, b) => {
    const confidenceOrder = { high: 0, medium: 1, low: 2 }
    return confidenceOrder[a.confidence] - confidenceOrder[b.confidence]
  })
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function getTrackClipsSorted(timeline: TimelineCanvasState, trackId: string): TimelineClip[] {
  const track = timeline.tracks[trackId]
  if (!track) return []

  return track.clipIds
    .map(id => timeline.clips[id])
    .filter((c): c is TimelineClip => c != null)
    .sort((a, b) => a.timing.start - b.timing.start)
}

// =============================================================================
// Timeline Analysis Engine
// =============================================================================
// Analyzes timeline structure and detects issues, warnings, and suggestions.
// Provides structural understanding of the timeline for intelligent editing.
// =============================================================================

import type { TimelineCanvasState, TimelineClip, TimelineTrack } from '../model/timeline'

// ---------------------------------------------------------------------------
// Analysis Report Types
// ---------------------------------------------------------------------------
export type IssueSeverity = 'error' | 'warning' | 'info'

export interface TimelineIssue {
  readonly id: string
  readonly severity: IssueSeverity
  readonly type: IssueType
  readonly message: string
  readonly clipIds: readonly string[]
  readonly trackIds: readonly string[]
  readonly autoFixable: boolean
}

export type IssueType =
  | 'OVERLAP'
  | 'GAP'
  | 'ORPHAN_CLIP'
  | 'SILENT_REGION'
  | 'EMPTY_TRACK'
  | 'TRACK_IMBALANCE'
  | 'MISSING_VIDEO'

export interface TrackDensity {
  readonly trackId: string
  readonly trackName: string
  readonly clipCount: number
  readonly totalDuration: number
  readonly coverage: number      // 0-1, percentage of timeline covered
  readonly averageGap: number    // average gap between clips
}

export interface TimelineAnalysisReport {
  readonly issues: readonly TimelineIssue[]
  readonly warnings: readonly TimelineIssue[]
  readonly suggestions: readonly TimelineIssue[]
  readonly trackDensity: readonly TrackDensity[]
  readonly overallHealth: number  // 0-100
  readonly analyzedAt: number
}

// ---------------------------------------------------------------------------
// Issue ID Generator
// ---------------------------------------------------------------------------
let issueCounter = 0
function generateIssueId(): string {
  return `issue-${Date.now()}-${++issueCounter}`
}

// ---------------------------------------------------------------------------
// Detect Overlaps
// ---------------------------------------------------------------------------
export function detectOverlaps(timeline: TimelineCanvasState): TimelineIssue[] {
  const issues: TimelineIssue[] = []

  for (const track of Object.values(timeline.tracks)) {
    const clips = getTrackClipsSorted(timeline, track.id)

    for (let i = 1; i < clips.length; i++) {
      const prev = clips[i - 1]
      const curr = clips[i]

      if (curr.timing.start < prev.timing.end) {
        const overlapDuration = prev.timing.end - curr.timing.start
        issues.push({
          id: generateIssueId(),
          severity: 'error',
          type: 'OVERLAP',
          message: `Clips "${prev.name}" and "${curr.name}" overlap by ${overlapDuration.toFixed(2)}s`,
          clipIds: [prev.id, curr.id],
          trackIds: [track.id],
          autoFixable: true,
        })
      }
    }
  }

  return issues
}

// ---------------------------------------------------------------------------
// Detect Gaps
// ---------------------------------------------------------------------------
export function detectGaps(timeline: TimelineCanvasState, threshold: number = 0.5): TimelineIssue[] {
  const issues: TimelineIssue[] = []

  for (const track of Object.values(timeline.tracks)) {
    if (track.type !== 'video') continue // Only check video tracks for gaps

    const clips = getTrackClipsSorted(timeline, track.id)
    if (clips.length < 2) continue

    for (let i = 1; i < clips.length; i++) {
      const prev = clips[i - 1]
      const curr = clips[i]
      const gap = curr.timing.start - prev.timing.end

      if (gap > threshold) {
        issues.push({
          id: generateIssueId(),
          severity: 'warning',
          type: 'GAP',
          message: `${gap.toFixed(2)}s gap between "${prev.name}" and "${curr.name}"`,
          clipIds: [prev.id, curr.id],
          trackIds: [track.id],
          autoFixable: true,
        })
      }
    }
  }

  return issues
}

// ---------------------------------------------------------------------------
// Detect Orphan Clips
// ---------------------------------------------------------------------------
export function detectOrphanClips(timeline: TimelineCanvasState): TimelineIssue[] {
  const issues: TimelineIssue[] = []

  // Find clips not referenced by any track
  for (const clip of Object.values(timeline.clips)) {
    const track = timeline.tracks[clip.trackId]
    if (!track || !track.clipIds.includes(clip.id)) {
      issues.push({
        id: generateIssueId(),
        severity: 'error',
        type: 'ORPHAN_CLIP',
        message: `Clip "${clip.name}" is not attached to any track`,
        clipIds: [clip.id],
        trackIds: [],
        autoFixable: false,
      })
    }
  }

  // Find track references to non-existent clips
  for (const track of Object.values(timeline.tracks)) {
    for (const clipId of track.clipIds) {
      if (!timeline.clips[clipId]) {
        issues.push({
          id: generateIssueId(),
          severity: 'error',
          type: 'ORPHAN_CLIP',
          message: `Track "${track.name}" references missing clip "${clipId}"`,
          clipIds: [],
          trackIds: [track.id],
          autoFixable: true,
        })
      }
    }
  }

  return issues
}

// ---------------------------------------------------------------------------
// Detect Silent Regions
// ---------------------------------------------------------------------------
export function detectSilentRegions(timeline: TimelineCanvasState, threshold: number = 2): TimelineIssue[] {
  const issues: TimelineIssue[] = []

  // Find video clips without corresponding audio
  const videoClips = Object.values(timeline.clips).filter(c => c.type === 'video')
  const audioClips = Object.values(timeline.clips).filter(c => c.type === 'audio')

  for (const videoClip of videoClips) {
    const hasAudio = audioClips.some(audioClip =>
      audioClip.timing.start <= videoClip.timing.start &&
      audioClip.timing.end >= videoClip.timing.end
    )

    if (!hasAudio && videoClip.timing.duration > threshold) {
      issues.push({
        id: generateIssueId(),
        severity: 'info',
        type: 'SILENT_REGION',
        message: `Video "${videoClip.name}" has no matching audio`,
        clipIds: [videoClip.id],
        trackIds: [],
        autoFixable: false,
      })
    }
  }

  return issues
}

// ---------------------------------------------------------------------------
// Detect Empty Tracks
// ---------------------------------------------------------------------------
export function detectEmptyTracks(timeline: TimelineCanvasState): TimelineIssue[] {
  const issues: TimelineIssue[] = []

  for (const track of Object.values(timeline.tracks)) {
    if (track.clipIds.length === 0) {
      issues.push({
        id: generateIssueId(),
        severity: 'info',
        type: 'EMPTY_TRACK',
        message: `Track "${track.name}" has no clips`,
        clipIds: [],
        trackIds: [track.id],
        autoFixable: true,
      })
    }
  }

  return issues
}

// ---------------------------------------------------------------------------
// Detect Missing Video
// ---------------------------------------------------------------------------
export function detectMissingVideo(timeline: TimelineCanvasState): TimelineIssue[] {
  const issues: TimelineIssue[] = []

  const hasVideo = Object.values(timeline.tracks).some(t => t.type === 'video' && t.clipIds.length > 0)

  if (!hasVideo && Object.values(timeline.tracks).length > 0) {
    issues.push({
      id: generateIssueId(),
      severity: 'error',
      type: 'MISSING_VIDEO',
      message: 'Timeline has no video content',
      clipIds: [],
      trackIds: [],
      autoFixable: false,
    })
  }

  return issues
}

// ---------------------------------------------------------------------------
// Analyze Track Density
// ---------------------------------------------------------------------------
export function analyzeTrackDensity(timeline: TimelineCanvasState): TrackDensity[] {
  return Object.values(timeline.tracks).map(track => {
    const clips = getTrackClipsSorted(timeline, track.id)
    const totalDuration = clips.reduce((sum, c) => sum + c.timing.duration, 0)
    const coverage = timeline.duration > 0 ? totalDuration / timeline.duration : 0

    // Calculate average gap
    let totalGap = 0
    let gapCount = 0
    for (let i = 1; i < clips.length; i++) {
      const gap = clips[i].timing.start - clips[i - 1].timing.end
      if (gap > 0) {
        totalGap += gap
        gapCount++
      }
    }
    const averageGap = gapCount > 0 ? totalGap / gapCount : 0

    return {
      trackId: track.id,
      trackName: track.name,
      clipCount: clips.length,
      totalDuration,
      coverage,
      averageGap,
    }
  })
}

// ---------------------------------------------------------------------------
// Analyze Track Imbalance
// ---------------------------------------------------------------------------
export function detectTrackImbalance(timeline: TimelineCanvasState): TimelineIssue[] {
  const issues: TimelineIssue[] = []
  const densities = analyzeTrackDensity(timeline)

  if (densities.length < 2) return issues

  const avgClipCount = densities.reduce((s, d) => s + d.clipCount, 0) / densities.length

  for (const density of densities) {
    if (density.clipCount > avgClipCount * 2 && density.clipCount > 5) {
      issues.push({
        id: generateIssueId(),
        severity: 'warning',
        type: 'TRACK_IMBALANCE',
        message: `Track "${density.trackName}" has ${density.clipCount} clips (avg: ${avgClipCount.toFixed(1)})`,
        clipIds: [],
        trackIds: [density.trackId],
        autoFixable: true,
      })
    }
  }

  return issues
}

// ---------------------------------------------------------------------------
// Full Analysis
// ---------------------------------------------------------------------------
export function analyzeTimeline(timeline: TimelineCanvasState): TimelineAnalysisReport {
  const overlaps = detectOverlaps(timeline)
  const gaps = detectGaps(timeline)
  const orphans = detectOrphanClips(timeline)
  const silentRegions = detectSilentRegions(timeline)
  const emptyTracks = detectEmptyTracks(timeline)
  const missingVideo = detectMissingVideo(timeline)
  const trackImbalance = detectTrackImbalance(timeline)
  const trackDensity = analyzeTrackDensity(timeline)

  const allIssues = [...overlaps, ...orphans, ...missingVideo]
  const allWarnings = [...gaps, ...trackImbalance]
  const allSuggestions = [...silentRegions, ...emptyTracks]

  // Calculate health score
  const errorCount = allIssues.length
  const warningCount = allWarnings.length
  const health = Math.max(0, 100 - (errorCount * 15) - (warningCount * 5))

  return {
    issues: allIssues,
    warnings: allWarnings,
    suggestions: allSuggestions,
    trackDensity,
    overallHealth: health,
    analyzedAt: Date.now(),
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function getTrackClipsSorted(timeline: TimelineCanvasState, trackId: string): TimelineClip[] {
  const track = timeline.tracks[trackId]
  if (!track) return []

  return track.clipIds
    .map(id => timeline.clips[id])
    .filter((c): c is TimelineClip => c != null)
    .sort((a, b) => a.timing.start - b.timing.start)
}

// =============================================================================
// Explainability Engine
// =============================================================================
// Generates human-readable explanations for intelligence decisions.
// Provides cause-effect chains for debugging and transparency.
// =============================================================================

import type { DecisionTrace, DecisionTraceNode } from './decisionTrace'
import { getTrace, getNodeChain, getTraceNodesByType, formatTraceDuration } from './decisionTrace'
import type { RuleExecution } from './ruleTracker'
import { globalRuleTracker } from './ruleTracker'

// ---------------------------------------------------------------------------
// Explanation Types
// ---------------------------------------------------------------------------
export interface Explanation {
  readonly id: string
  readonly title: string
  readonly summary: string
  readonly steps: readonly ExplanationStep[]
  readonly confidence: number
  readonly duration: number
}

export interface ExplanationStep {
  readonly order: number
  readonly description: string
  readonly ruleId: string
  readonly confidence: number
  readonly timestamp: number
}

// ---------------------------------------------------------------------------
// Explain a Suggestion
// ---------------------------------------------------------------------------
export function explainSuggestion(suggestionId: string, trace: DecisionTrace | null): Explanation {
  if (!trace) {
    return {
      id: suggestionId,
      title: 'Suggestion',
      summary: 'No trace available for this suggestion',
      steps: [],
      confidence: 0,
      duration: 0,
    }
  }

  const suggestionNodes = getTraceNodesByType(trace, 'SUGGEST')
  const relatedNode = suggestionNodes.find(n =>
    n.metadata.suggestionId === suggestionId
  )

  if (!relatedNode) {
    return {
      id: suggestionId,
      title: 'Suggestion',
      summary: 'No trace node found for this suggestion',
      steps: [],
      confidence: 0,
      duration: 0,
    }
  }

  const chain = getNodeChain(relatedNode.id, trace)
  const steps: ExplanationStep[] = chain.map((node, i) => ({
    order: i + 1,
    description: node.explanation,
    ruleId: node.ruleId,
    confidence: node.confidence,
    timestamp: node.timestamp,
  }))

  return {
    id: suggestionId,
    title: `Suggestion: ${relatedNode.metadata.title ?? suggestionId}`,
    summary: relatedNode.explanation,
    steps,
    confidence: relatedNode.confidence,
    duration: trace.completedAt ? trace.completedAt - trace.startedAt : 0,
  }
}

// ---------------------------------------------------------------------------
// Explain an Auto Layout Operation
// ---------------------------------------------------------------------------
export function explainAutoLayout(traceId: string): Explanation {
  const trace = getTrace(traceId)

  if (!trace) {
    return {
      id: traceId,
      title: 'Auto Layout',
      summary: 'No trace available',
      steps: [],
      confidence: 0,
      duration: 0,
    }
  }

  const layoutNodes = getTraceNodesByType(trace, 'LAYOUT')
  const steps: ExplanationStep[] = layoutNodes.map((node, i) => ({
    order: i + 1,
    description: node.explanation,
    ruleId: node.ruleId,
    confidence: node.confidence,
    timestamp: node.timestamp,
  }))

  const avgConfidence = layoutNodes.length > 0
    ? layoutNodes.reduce((s, n) => s + n.confidence, 0) / layoutNodes.length
    : 0

  return {
    id: traceId,
    title: 'Auto Layout',
    summary: `Applied ${layoutNodes.length} layout operations`,
    steps,
    confidence: avgConfidence,
    duration: trace.completedAt ? trace.completedAt - trace.startedAt : 0,
  }
}

// ---------------------------------------------------------------------------
// Explain a Conflict Resolution
// ---------------------------------------------------------------------------
export function explainConflictResolution(traceId: string): Explanation {
  const trace = getTrace(traceId)

  if (!trace) {
    return {
      id: traceId,
      title: 'Conflict Resolution',
      summary: 'No trace available',
      steps: [],
      confidence: 0,
      duration: 0,
    }
  }

  const resolveNodes = getTraceNodesByType(trace, 'RESOLVE')
  const steps: ExplanationStep[] = []

  for (const node of resolveNodes) {
    const chain = getNodeChain(node.id, trace)
    for (const chainNode of chain) {
      if (!steps.find(s => s.ruleId === chainNode.ruleId && s.timestamp === chainNode.timestamp)) {
        steps.push({
          order: steps.length + 1,
          description: chainNode.explanation,
          ruleId: chainNode.ruleId,
          confidence: chainNode.confidence,
          timestamp: chainNode.timestamp,
        })
      }
    }
  }

  const avgConfidence = resolveNodes.length > 0
    ? resolveNodes.reduce((s, n) => s + n.confidence, 0) / resolveNodes.length
    : 0

  return {
    id: traceId,
    title: 'Conflict Resolution',
    summary: `Resolved ${resolveNodes.length} conflicts`,
    steps,
    confidence: avgConfidence,
    duration: trace.completedAt ? trace.completedAt - trace.startedAt : 0,
  }
}

// ---------------------------------------------------------------------------
// Explain a Rule Execution
// ---------------------------------------------------------------------------
export function explainRuleExecution(execution: RuleExecution): Explanation {
  const steps: ExplanationStep[] = execution.intermediateStates.map((state, i) => ({
    order: i + 1,
    description: state.label,
    ruleId: execution.ruleId,
    confidence: execution.confidence,
    timestamp: state.timestamp,
  }))

  return {
    id: execution.id,
    title: `Rule: ${execution.ruleId}`,
    summary: `Executed in ${execution.durationMs}ms with ${(execution.confidence * 100).toFixed(0)}% confidence`,
    steps,
    confidence: execution.confidence,
    duration: execution.durationMs,
  }
}

// ---------------------------------------------------------------------------
// Format Explanation as Text
// ---------------------------------------------------------------------------
export function formatExplanationAsText(explanation: Explanation): string {
  const lines: string[] = []

  lines.push(`=== ${explanation.title} ===`)
  lines.push(`Summary: ${explanation.summary}`)
  lines.push(`Confidence: ${(explanation.confidence * 100).toFixed(0)}%`)
  lines.push(`Duration: ${explanation.duration}ms`)
  lines.push('')

  if (explanation.steps.length > 0) {
    lines.push('Steps:')
    for (const step of explanation.steps) {
      lines.push(`  ${step.order}. ${step.description} (${(step.confidence * 100).toFixed(0)}% confidence)`)
    }
  }

  return lines.join('\n')
}

// ---------------------------------------------------------------------------
// Format Explanation as Markdown
// ---------------------------------------------------------------------------
export function formatExplanationAsMarkdown(explanation: Explanation): string {
  const lines: string[] = []

  lines.push(`## ${explanation.title}`)
  lines.push('')
  lines.push(`**Summary:** ${explanation.summary}`)
  lines.push(`**Confidence:** ${(explanation.confidence * 100).toFixed(0)}%`)
  lines.push(`**Duration:** ${explanation.duration}ms`)
  lines.push('')

  if (explanation.steps.length > 0) {
    lines.push('### Decision Steps')
    lines.push('')
    for (const step of explanation.steps) {
      lines.push(`${step.order}. ${step.description}`)
      lines.push(`   - Confidence: ${(step.confidence * 100).toFixed(0)}%`)
      lines.push(`   - Rule: \`${step.ruleId}\``)
      lines.push('')
    }
  }

  return lines.join('\n')
}

// =============================================================================
// Intelligence Replay System
// =============================================================================
// Enables deterministic replay of intelligence operations.
// Used for debugging, testing, and reproducing decisions.
// =============================================================================

import type { TimelineCanvasState } from '../../model/timeline'
import type { DecisionTrace, DecisionTraceNode } from './decisionTrace'
import {
  DecisionTraceBuilder,
  storeTrace,
  getTrace,
  hashTimelineState,
} from './decisionTrace'
import { analyzeTimeline, type TimelineAnalysisReport } from '../timelineAnalyzer'
import { generateSuggestions, type Suggestion } from '../suggestionEngine'
import { detectConflicts, resolveTimelineConflicts, type ResolutionResult } from '../conflictResolver'
import { autoStackClips, compactTimeline, type LayoutResult } from '../autoLayout'

// ---------------------------------------------------------------------------
// Replay Result
// ---------------------------------------------------------------------------
export interface ReplayResult {
  readonly traceId: string
  readonly success: boolean
  readonly steps: readonly ReplayStep[]
  readonly finalState: TimelineCanvasState
  readonly errors: readonly string[]
}

export interface ReplayStep {
  readonly order: number
  readonly type: string
  readonly description: string
  readonly inputHash: string
  readonly outputHash: string
  readonly success: boolean
}

// ---------------------------------------------------------------------------
// Replay Analysis
// ---------------------------------------------------------------------------
export function replayAnalysis(timeline: TimelineCanvasState): {
  report: TimelineAnalysisReport
  trace: DecisionTrace
} {
  const builder = new DecisionTraceBuilder('Timeline Analysis Replay')

  // Track analysis steps
  const report = analyzeTimeline(timeline)

  builder.addNode(
    'ANALYZE',
    'detectOverlaps',
    timeline,
    report.issues.filter(i => i.type === 'OVERLAP'),
    `Detected ${report.issues.filter(i => i.type === 'OVERLAP').length} overlaps`,
    1.0,
    [],
    { issueCount: report.issues.filter(i => i.type === 'OVERLAP').length }
  )

  builder.addNode(
    'ANALYZE',
    'detectGaps',
    timeline,
    report.warnings.filter(w => w.type === 'GAP'),
    `Detected ${report.warnings.filter(w => w.type === 'GAP').length} gaps`,
    1.0,
    [],
    { warningCount: report.warnings.filter(w => w.type === 'GAP').length }
  )

  builder.addNode(
    'ANALYZE',
    'calculateHealth',
    timeline,
    report.overallHealth,
    `Health score: ${report.overallHealth}%`,
    1.0,
    [],
    { health: report.overallHealth }
  )

  const trace = builder.build()
  storeTrace(trace)

  return { report, trace }
}

// ---------------------------------------------------------------------------
// Replay Suggestions
// ---------------------------------------------------------------------------
export function replaySuggestions(timeline: TimelineCanvasState): {
  suggestions: Suggestion[]
  trace: DecisionTrace
} {
  const builder = new DecisionTraceBuilder('Suggestion Generation Replay')

  const suggestions = generateSuggestions(timeline)

  for (const suggestion of suggestions) {
    builder.addNode(
      'SUGGEST',
      `suggest_${suggestion.type.toLowerCase()}`,
      timeline,
      suggestion,
      suggestion.description,
      suggestion.confidence === 'high' ? 0.9 : suggestion.confidence === 'medium' ? 0.7 : 0.5,
      [],
      {
        suggestionId: suggestion.id,
        title: suggestion.title,
        type: suggestion.type,
        confidence: suggestion.confidence,
      }
    )
  }

  const trace = builder.build()
  storeTrace(trace)

  return { suggestions, trace }
}

// ---------------------------------------------------------------------------
// Replay Conflict Resolution
// ---------------------------------------------------------------------------
export function replayConflictResolution(
  timeline: TimelineCanvasState,
  strategy: 'SHIFT_RIGHT' | 'TRIM_CLIP' | 'MERGE_TRACK' = 'SHIFT_RIGHT'
): {
  result: ResolutionResult
  trace: DecisionTrace
} {
  const builder = new DecisionTraceBuilder('Conflict Resolution Replay')

  const conflicts = detectConflicts(timeline)

  builder.addNode(
    'ANALYZE',
    'detectConflicts',
    timeline,
    conflicts,
    `Detected ${conflicts.length} conflicts`,
    1.0,
    [],
    { conflictCount: conflicts.length }
  )

  const result = resolveTimelineConflicts(timeline, strategy)

  for (const conflict of conflicts) {
    builder.addNode(
      'RESOLVE',
      `resolve_${strategy.toLowerCase()}`,
      conflict,
      result.description,
      `Resolved conflict between "${conflict.clipA.name}" and "${conflict.clipB.name}"`,
      0.9,
      [],
      {
        conflictId: conflict.id,
        strategy,
        overlapDuration: conflict.overlapDuration,
      }
    )
  }

  const trace = builder.build()
  storeTrace(trace)

  return { result, trace }
}

// ---------------------------------------------------------------------------
// Replay Auto Layout
// ---------------------------------------------------------------------------
export function replayAutoLayout(
  timeline: TimelineCanvasState,
  operation: 'stack' | 'compact' = 'stack'
): {
  result: LayoutResult
  trace: DecisionTrace
} {
  const builder = new DecisionTraceBuilder(`Auto Layout Replay (${operation})`)

  const result = operation === 'stack'
    ? autoStackClips(timeline)
    : compactTimeline(timeline)

  builder.addNode(
    'LAYOUT',
    `auto_${operation}`,
    timeline,
    result,
    result.description,
    0.9,
    [],
    {
      operation,
      affectedClips: result.affectedClips,
    }
  )

  const trace = builder.build()
  storeTrace(trace)

  return { result, trace }
}

// ---------------------------------------------------------------------------
// Full Deterministic Replay
// ---------------------------------------------------------------------------
export function fullReplay(timeline: TimelineCanvasState): ReplayResult {
  const builder = new DecisionTraceBuilder('Full Intelligence Replay')
  const steps: ReplayStep[] = []
  const errors: string[] = []
  let stepOrder = 0

  // Step 1: Analysis
  try {
    const analysisInput = timeline
    const report = analyzeTimeline(timeline)
    stepOrder++
    steps.push({
      order: stepOrder,
      type: 'ANALYZE',
      description: `Analysis: ${report.issues.length} issues, ${report.warnings.length} warnings`,
      inputHash: hashTimelineState(analysisInput),
      outputHash: hashTimelineState(report),
      success: true,
    })

    builder.addNode(
      'ANALYZE',
      'full_analysis',
      analysisInput,
      report,
      `Found ${report.issues.length} issues and ${report.warnings.length} warnings`,
      1.0
    )
  } catch (e) {
    errors.push(`Analysis failed: ${e}`)
  }

  // Step 2: Suggestions
  try {
    const suggestionsInput = timeline
    const suggestions = generateSuggestions(timeline)
    stepOrder++
    steps.push({
      order: stepOrder,
      type: 'SUGGEST',
      description: `Generated ${suggestions.length} suggestions`,
      inputHash: hashTimelineState(suggestionsInput),
      outputHash: hashTimelineState(suggestions),
      success: true,
    })

    builder.addNode(
      'SUGGEST',
      'full_suggestions',
      suggestionsInput,
      suggestions,
      `Generated ${suggestions.length} suggestions`,
      0.8
    )
  } catch (e) {
    errors.push(`Suggestions failed: ${e}`)
  }

  // Step 3: Conflict Detection
  try {
    const conflictsInput = timeline
    const conflicts = detectConflicts(timeline)
    stepOrder++
    steps.push({
      order: stepOrder,
      type: 'RESOLVE',
      description: `Detected ${conflicts.length} conflicts`,
      inputHash: hashTimelineState(conflictsInput),
      outputHash: hashTimelineState(conflicts),
      success: true,
    })

    builder.addNode(
      'RESOLVE',
      'detect_conflicts',
      conflictsInput,
      conflicts,
      `Detected ${conflicts.length} conflicts`,
      1.0
    )
  } catch (e) {
    errors.push(`Conflict detection failed: ${e}`)
  }

  const trace = builder.build()
  storeTrace(trace)

  return {
    traceId: trace.id,
    success: errors.length === 0,
    steps,
    finalState: timeline,
    errors,
  }
}

// =============================================================================
// Rule Execution Tracker
// =============================================================================
// Tracks execution of intelligence rules with timing and confidence metrics.
// Stores intermediate states for debugging and replay.
// =============================================================================

import type { DecisionTraceNode, TraceNodeType } from './decisionTrace'
import { generateNodeId, hashTimelineState } from './decisionTrace'

// ---------------------------------------------------------------------------
// Rule Execution Record
// ---------------------------------------------------------------------------
export interface RuleExecution {
  readonly id: string
  readonly ruleId: string
  readonly ruleType: TraceNodeType
  readonly inputHash: string
  readonly outputHash: string
  readonly startedAt: number
  readonly completedAt: number
  readonly durationMs: number
  readonly success: boolean
  readonly confidence: number
  readonly intermediateStates: readonly IntermediateState[]
  readonly error?: string
}

export interface IntermediateState {
  readonly label: string
  readonly stateHash: string
  readonly timestamp: number
}

// ---------------------------------------------------------------------------
// Rule Tracker
// ---------------------------------------------------------------------------
export class RuleTracker {
  private executions: RuleExecution[] = []
  private currentExecution: Partial<RuleExecution> | null = null
  private intermediateStates: IntermediateState[] = []
  private maxExecutions: number

  constructor(maxExecutions: number = 200) {
    this.maxExecutions = maxExecutions
  }

  startExecution(ruleId: string, ruleType: TraceNodeType, input: unknown): void {
    this.currentExecution = {
      id: generateNodeId(),
      ruleId,
      ruleType,
      inputHash: hashTimelineState(input),
      startedAt: Date.now(),
      intermediateStates: [],
    }
    this.intermediateStates = []
  }

  recordIntermediate(label: string, state: unknown): void {
    this.intermediateStates.push({
      label,
      stateHash: hashTimelineState(state),
      timestamp: Date.now(),
    })
  }

  completeExecution(output: unknown, confidence: number, success: boolean = true, error?: string): RuleExecution {
    if (!this.currentExecution) {
      throw new Error('No execution in progress')
    }

    const now = Date.now()
    const execution: RuleExecution = {
      id: this.currentExecution.id!,
      ruleId: this.currentExecution.ruleId!,
      ruleType: this.currentExecution.ruleType!,
      inputHash: this.currentExecution.inputHash!,
      outputHash: hashTimelineState(output),
      startedAt: this.currentExecution.startedAt!,
      completedAt: now,
      durationMs: now - this.currentExecution.startedAt!,
      success,
      confidence,
      intermediateStates: [...this.intermediateStates],
      error,
    }

    this.executions.push(execution)

    // Trim old executions
    if (this.executions.length > this.maxExecutions) {
      this.executions = this.executions.slice(-this.maxExecutions)
    }

    this.currentExecution = null
    this.intermediateStates = []

    return execution
  }

  getExecutions(): readonly RuleExecution[] {
    return [...this.executions]
  }

  getExecutionsByRule(ruleId: string): readonly RuleExecution[] {
    return this.executions.filter(e => e.ruleId === ruleId)
  }

  getExecutionsByType(ruleType: TraceNodeType): readonly RuleExecution[] {
    return this.executions.filter(e => e.ruleType === ruleType)
  }

  getAverageConfidence(ruleId: string): number {
    const ruleExecutions = this.getExecutionsByRule(ruleId)
    if (ruleExecutions.length === 0) return 0
    const sum = ruleExecutions.reduce((s, e) => s + e.confidence, 0)
    return sum / ruleExecutions.length
  }

  getAverageDuration(ruleId: string): number {
    const ruleExecutions = this.getExecutionsByRule(ruleId)
    if (ruleExecutions.length === 0) return 0
    const sum = ruleExecutions.reduce((s, e) => s + e.durationMs, 0)
    return sum / ruleExecutions.length
  }

  getSuccessRate(ruleId: string): number {
    const ruleExecutions = this.getExecutionsByRule(ruleId)
    if (ruleExecutions.length === 0) return 1
    const successes = ruleExecutions.filter(e => e.success).length
    return successes / ruleExecutions.length
  }

  clear(): void {
    this.executions = []
    this.currentExecution = null
    this.intermediateStates = []
  }
}

// ---------------------------------------------------------------------------
// Global Rule Tracker Instance
// ---------------------------------------------------------------------------
export const globalRuleTracker = new RuleTracker()

// ---------------------------------------------------------------------------
// Helper: Track a rule execution
// ---------------------------------------------------------------------------
export function trackRuleExecution<T>(
  ruleId: string,
  ruleType: TraceNodeType,
  input: unknown,
  ruleFn: () => T,
  confidenceExtractor: (result: T) => number = () => 1.0
): T {
  globalRuleTracker.startExecution(ruleId, ruleType, input)

  try {
    const result = ruleFn()
    const confidence = confidenceExtractor(result)
    globalRuleTracker.completeExecution(result, confidence, true)
    return result
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error'
    globalRuleTracker.completeExecution(null, 0, false, message)
    throw error
  }
}

// ---------------------------------------------------------------------------
// Helper: Measure rule confidence from historical execution
// ---------------------------------------------------------------------------
export function measureRuleConfidence(ruleId: string): number {
  return globalRuleTracker.getAverageConfidence(ruleId)
}

// ---------------------------------------------------------------------------
// Helper: Get rule statistics
// ---------------------------------------------------------------------------
export function getRuleStats(ruleId: string): {
  executions: number
  avgConfidence: number
  avgDuration: number
  successRate: number
} {
  const tracker = globalRuleTracker
  return {
    executions: tracker.getExecutionsByRule(ruleId).length,
    avgConfidence: tracker.getAverageConfidence(ruleId),
    avgDuration: tracker.getAverageDuration(ruleId),
    successRate: tracker.getSuccessRate(ruleId),
  }
}
